CREATE OR REPLACE FUNCTION public.accept_lab_result(p_result uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r     lab_result;
  role_ app_role;
begin
  select * into r from lab_result where id = p_result;
  if not found then raise exception 'No such lab result: %', p_result; end if;

  role_ := public.current_app_role();
  if role_ is not null and role_ not in ('lab_tech','supervisor') then
    raise exception
      'A % may not accept a lab result as final. ROLE_AND_APPROVAL_MODEL ticks this for the lab '
      'technician and the supervisor only.', role_
      using errcode = 'insufficient_privilege';
  end if;

  if r.superseded_by_result_id is not null then
    raise exception
      'That result has been superseded by a retest. Accept the current version instead — accepting '
      'a superseded reading would make the record say the batch was cleared on a number that has '
      'been replaced.'
      using errcode = 'invalid_parameter_value';
  end if;

  update lab_result
     set accepted = true, accepted_by = auth.uid(), accepted_at = now()
   where id = p_result;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), role_, 'accept_lab_result', 'lab_result', p_result::text,
          jsonb_build_object('verdict', r.verdict, 'version', r.version),
          coalesce(p_reason, 'Result accepted as final · verdict ' || r.verdict));
end;
$function$

CREATE OR REPLACE FUNCTION public.accept_with_deviation(p_deviation uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d deviation; protected boolean;
begin
  perform public.assert_role(array['supervisor','gm']::app_role[], 'Accept-with-deviation');

  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Accept-with-deviation needs a reason — it goes on the record permanently';
  end if;

  select * into d from deviation where id = p_deviation;
  if not found then raise exception 'No such deviation: %', p_deviation; end if;
  if d.state <> 'open' then
    raise exception 'Deviation is already %, not open', d.state;
  end if;

  -- A protected gate is the one thing a supervisor cannot wave through. §3.2.
  select coalesce(g.is_protected, false) into protected
  from gate_rule g where g.id = d.gate_rule_id;

  if protected and not public.has_role('gm') then
    raise exception
      'This gate is protected — a supervisor cannot accept it. Escalate it for a GM override.'
      using errcode = 'insufficient_privilege';
  end if;

  update deviation
     set state = 'accepted', decided_at = now(), decided_by = auth.uid(),
         decided_by_role = public.current_app_role(), decision_reason = p_reason
   where id = p_deviation;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'accept_with_deviation', 'deviation',
          p_deviation::text, p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.add_corrective_action(p_deviation uuid, p_description text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare new_id uuid;
begin
  perform public.assert_role(array['supervisor','gm','lab_tech']::app_role[],
                             'Recording a corrective action');
  insert into corrective_action (deviation_id, description, created_by)
  values (p_deviation, p_description, auth.uid())
  returning id into new_id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'add_corrective_action', 'corrective_action',
          new_id::text, p_description);
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.allocate_vessel(p_batch uuid, p_scope text, p_instance_no integer, p_location uuid, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  m        vessel_scope_map;
  loc      location;
  clash    record;
  new_id   uuid;
begin
  select * into m from vessel_scope_map where scope = p_scope;
  if not found then
    raise exception 'Unknown process scope "%". Vessel scopes come from vessel_scope_map.', p_scope;
  end if;
  if m.location_kind is null then
    raise exception 'Scope "%" is not held in a vessel: %', p_scope, m.unmapped_reason
      using errcode = 'invalid_parameter_value';
  end if;

  select * into loc from location where id = p_location;
  if not found then raise exception 'No such location: %', p_location; end if;

  if loc.kind <> m.location_kind then
    raise exception '% needs a % — % is a %.',
      p_scope, m.location_kind, loc.label, loc.kind
      using errcode = 'invalid_parameter_value';
  end if;

  if loc.status is distinct from 'available' then
    raise exception '% is not available (status: %).', loc.label, loc.status
      using errcode = 'invalid_parameter_value';
  end if;

  -- The double-allocation warning the document asks for, as a refusal. Only meaningful for an
  -- exclusive vessel; the yard is shared on purpose.
  if loc.is_exclusive then
    select mb.code, o.started_at into clash
      from location_occupancy o
      join master_batch mb on mb.id = o.master_batch_id
     where o.location_id = p_location
       and o.ended_at is null
       and o.master_batch_id <> p_batch
     limit 1;
    if found then
      raise exception '% is occupied by % since %, and has not been released.',
        loc.label, clash.code, to_char(clash.started_at, 'DD Mon HH24:MI')
        using errcode = 'exclusion_violation';
    end if;
  end if;

  insert into batch_vessel_allocation
    (master_batch_id, scope, instance_no, location_id, conflict_id, note, allocated_by)
  values (p_batch, p_scope, p_instance_no, p_location, m.conflict_id, p_note, auth.uid())
  on conflict (master_batch_id, scope, instance_no) do update set
    location_id  = excluded.location_id,
    conflict_id  = excluded.conflict_id,
    note         = excluded.note,
    allocated_by = excluded.allocated_by,
    allocated_at = now()
  returning id into new_id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'allocate_vessel', 'batch_vessel_allocation',
          new_id::text,
          jsonb_build_object('scope', p_scope, 'instance_no', p_instance_no, 'location', loc.code),
          format('%s %s of this batch is %s', p_scope, p_instance_no, loc.label));
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.assert_may_execute(p_activity uuid, p_action text)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r   app_role;
  own app_role;
  ttl text;
begin
  select ba.responsible_role, ba.title into own, ttl
    from batch_activity ba where ba.id = p_activity;

  -- 0067 · NOT FOUND IS NOT THIS FUNCTION'S BUSINESS.
  -- Raising here turned start_activity's long-standing silent no-op on an unknown id into a 400,
  -- and failed a probe that was asking whether an OPERATOR MAY START WORK — not whether that
  -- particular uuid exists. Authorisation is the question; existence belongs to the caller.
  if not found then
    return;
  end if;

  r := public.current_app_role();

  -- A supervisor and above may perform eligible downstream work — ROLE_AND_APPROVAL_MODEL §2.
  if r in ('supervisor', 'manager', 'admin', 'gm') then
    return;
  end if;

  if own is null or r is distinct from own then
    raise exception
      '% is %''s work, not a %''s. A % may execute the work their role is responsible for; a '
      'supervisor may take eligible downstream work. Ask a supervisor to reassign it.',
      ttl, coalesce(own::text, 'nobody'), coalesce(r::text, 'caller with no role'),
      coalesce(r::text, 'caller with no role')
      using errcode = 'insufficient_privilege';
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_activity(p_activity uuid, p_person uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ba batch_activity; b master_batch; prev uuid;
begin
  select * into ba from batch_activity where id = p_activity;
  select * into b from master_batch where id = ba.master_batch_id;

  if b.status = 'active' and coalesce(p_reason,'') = '' then
    raise exception 'A forced assignment on a running batch needs a reason';
  end if;

  prev := ba.assigned_person_id;
  update batch_activity
     set assigned_person_id = p_person, assignment_reason = p_reason
   where id = p_activity;

  -- Notify both sides of the change, not just the new assignee.
  insert into notification (master_batch_id, batch_activity_id, to_person_id, to_role, kind, message, reason, sent_by)
  select ba.master_batch_id, p_activity, p_person, ba.responsible_role, 'assignment',
         ba.title || ' — ' || ba.scope_label || ' assigned to you', p_reason, auth.uid();

  if prev is not null and prev <> p_person then
    insert into notification (master_batch_id, batch_activity_id, to_person_id, to_role, kind, message, reason, sent_by)
    values (ba.master_batch_id, p_activity, prev, ba.responsible_role, 'assignment',
            ba.title || ' — ' || ba.scope_label || ' reassigned away from you', p_reason, auth.uid());
  end if;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'assign_activity', 'batch_activity', p_activity::text,
          jsonb_build_object('person', p_person), p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.bind_evidence(p_activity uuid, p_requirement_key text, p_storage_path text, p_media_kind text DEFAULT 'photo'::text, p_supersedes uuid DEFAULT NULL::uuid, p_supersede_reason text DEFAULT NULL::text)
 RETURNS TABLE(media_id uuid, requirement_key text, satisfied_count integer, min_count integer, uploaded_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba      batch_activity;
  req     batch_activity_evidence_req;
  obj     record;
  segs    text[];
  new_id  uuid;
  live    int;
begin
  if auth.uid() is null then
    raise exception 'bind_evidence needs a signed-in user — the uploader is taken from the JWT, never from a parameter'
      using errcode = 'insufficient_privilege';
  end if;

  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;

  -- 5 · entitlement first, so an unauthorised caller learns nothing about the rest.
  if not public.can_capture_for_activity(p_activity) then
    raise exception
      'Not permitted: % may not capture evidence for %. Evidence is captured by the assigned '
      'operator or lab technician, or by a supervisor (ROLE_AND_APPROVAL_MODEL §2).',
      coalesce(public.current_app_role()::text, 'an unknown role'), ba.title
      using errcode = 'insufficient_privilege';
  end if;

  -- 3 · the requirement must be this activity's.
  select * into req from batch_activity_evidence_req
   where batch_activity_id = p_activity and key = p_requirement_key;
  if not found then
    raise exception 'Activity % has no evidence requirement named %', ba.title, p_requirement_key;
  end if;

  -- 4 · the kind must be one this requirement accepts.
  if not (p_media_kind = any (req.media_kinds)) then
    raise exception '% accepts % — % was offered',
      req.label, array_to_string(req.media_kinds, ' or '), p_media_kind;
  end if;

  -- 2 · the path must name this batch and this activity.
  segs := string_to_array(p_storage_path, '/');
  if array_length(segs, 1) <> 3
     or segs[1] <> ba.master_batch_id::text
     or segs[2] <> p_activity::text then
    raise exception
      'Storage path % does not belong to this activity. Expected %/%/<file>',
      p_storage_path, ba.master_batch_id, p_activity;
  end if;

  -- 1 · THE INTEGRITY RULE. The object has to be there already.
  select o.id, o.metadata into obj
    from storage.objects o
   where o.bucket_id = 'evidence' and o.name = p_storage_path;
  if not found then
    raise exception
      'No object at evidence/% — upload the file first, then bind it. A row claiming a photograph '
      'that is not in storage is a false record.', p_storage_path
      using errcode = 'no_data_found';
  end if;

  -- 0071 · AN EMPTY FILE IS NOT A PHOTOGRAPH.
  --
  -- The object-exists rule above asks whether something is in storage. It does not ask whether that
  -- something is anything. A zero-byte upload was accepted and bound, and satisfied the requirement
  -- outright — satisfied_count 1 of 1 — so an evidence gate could be cleared with nothing at all.
  -- That is not a hypothetical: a camera that fails, a file picker cancelled at the wrong instant
  -- and a dropped connection all produce exactly this, and the operator is then told they are done.
  --
  -- Found by uploading Buffer.alloc(0) as a real signed-in operator.
  if coalesce(nullif(obj.metadata->>'size', '')::bigint, 0) <= 0 then
    raise exception
      'The file uploaded for % is empty (0 bytes). That is usually a photograph that did not '
      'capture, or an upload cut short. Take it again.', req.label
      using errcode = 'check_violation';
  end if;

  -- 6 · already satisfied? Only an explicit retake may proceed.
  select count(*) into live from evidence_media
   where requirement_id = req.id and superseded_by_id is null;

  if p_supersedes is null and live >= req.min_count then
    raise exception
      '% already has % of % item(s). Pass the id of the item this one replaces, with a reason.',
      req.label, live, req.min_count;
  end if;

  if p_supersedes is not null then
    if coalesce(trim(p_supersede_reason), '') = '' then
      raise exception 'Replacing an evidence item needs a reason — the original is kept, not deleted';
    end if;
    if not exists (
      select 1 from evidence_media
       where id = p_supersedes and requirement_id = req.id and superseded_by_id is null
    ) then
      raise exception 'No live evidence item % on %', p_supersedes, req.label;
    end if;
  end if;

  insert into evidence_media (
    master_batch_id, batch_activity_id, requirement_id, requirement_key,
    storage_path, media_kind, mime_type, byte_size, uploaded_by
  ) values (
    ba.master_batch_id, p_activity, req.id, req.key,
    p_storage_path, p_media_kind,
    nullif(obj.metadata->>'mimetype', ''),
    nullif(obj.metadata->>'size', '')::bigint,
    auth.uid()
  )
  returning id into new_id;

  -- §6 — retaking does not delete. The original stays, pointing at what replaced it.
  if p_supersedes is not null then
    update evidence_media
       set superseded_by_id = new_id, superseded_reason = p_supersede_reason
     where id = p_supersedes;
  end if;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'bind_evidence', 'evidence_media', new_id::text,
          jsonb_build_object('activity', p_activity, 'requirement', req.key, 'path', p_storage_path),
          case when p_supersedes is null then 'Evidence captured for ' || req.label
               else 'Retake of ' || req.label || ': ' || p_supersede_reason end);

  return query
    select new_id, req.key, r.satisfied_count, r.min_count,
           (select m.uploaded_at from evidence_media m where m.id = new_id)
      from batch_activity_evidence_req r where r.id = req.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_batch(p_batch uuid, p_reason text)
 RETURNS TABLE(activities_cancelled integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b master_batch;
  n int := 0;
begin
  perform public.assert_role(array['admin', 'gm']::app_role[], 'cancel a batch');

  if coalesce(trim(p_reason), '') = '' then
    raise exception 'Cancelling a batch needs a reason — it is a decision, and the record has to say whose and why';
  end if;

  select * into b from master_batch where id = p_batch;
  if not found then raise exception 'No such batch: %', p_batch; end if;

  if b.status = 'cancelled' then
    return query select 0;
    return;
  end if;
  if b.status = 'closed' then
    raise exception 'Batch % is closed. A finished batch is not cancelled retrospectively', b.code;
  end if;

  update master_batch set status = 'cancelled' where id = p_batch;

  update batch_activity
     set state = 'CANCELLED',
         blocked_reason = p_reason
   where master_batch_id = p_batch
     and state not in ('COMPLETED','SKIPPED','CANCELLED');
  get diagnostics n = row_count;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'cancel_batch', 'master_batch', p_batch::text,
          jsonb_build_object('status', 'cancelled', 'activities_cancelled', n), p_reason);

  return query select n;
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_extension(p_request uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare er extension_request;
begin
  select * into er from extension_request where id = p_request for update;
  if not found then raise exception 'No such extension request: %', p_request; end if;

  -- Only the person who asked, and only while nobody has answered. A supervisor
  -- who wants a request gone rejects it; withdrawing somebody else's request
  -- would erase the fact that it was made.
  if er.requested_by is distinct from auth.uid() then
    raise exception 'Only the requester may cancel an extension request';
  end if;
  if er.status <> 'REQUESTED' then
    raise exception 'Extension request is % — it can no longer be withdrawn', er.status;
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'A cancellation needs a reason';
  end if;

  update extension_request set
    status = 'CANCELLED', cancelled_at = now(), cancelled_by = auth.uid(),
    cancel_reason = trim(p_reason)
  where id = p_request;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'cancel_extension', 'extension_request',
          p_request::text, trim(p_reason));
end;
$function$

CREATE OR REPLACE FUNCTION public.cancel_monthly_schedule_group(p_group uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if auth.uid() is null or not public.has_role('admin') then
    raise exception 'Only an Admin can cancel a scheduled group';
  end if;

  update public.monthly_schedule_group
     set status = 'cancelled'
   where id = p_group
     and status = 'scheduled';

  if not found then
    raise exception 'Only a scheduled group can be cancelled';
  end if;

  insert into public.audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state)
  values (auth.uid(), public.current_app_role(), 'cancel_monthly_schedule_group',
          'monthly_schedule_group', p_group::text, jsonb_build_object('status', 'cancelled'));
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_monthly_schedule_group(p_schedule_group uuid, p_master_batch uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_group public.monthly_schedule_group;
  v_batch public.master_batch;
begin
  if auth.uid() is null or not public.has_role('admin') then
    raise exception 'Only an Admin can create a Master Batch from the monthly schedule';
  end if;

  select * into v_group from public.monthly_schedule_group where id = p_schedule_group for update;
  select * into v_batch from public.master_batch where id = p_master_batch for update;

  if not found or v_group.id is null then
    raise exception 'The scheduled batch group no longer exists';
  end if;
  if v_batch.id is null then
    raise exception 'The Master Batch was not created';
  end if;
  if v_group.status <> 'scheduled' or v_group.master_batch_id is not null then
    raise exception 'This scheduled group has already been used';
  end if;
  if v_batch.status <> 'draft' then
    raise exception 'Only a draft Master Batch can be linked to the schedule';
  end if;
  if v_batch.code <> v_group.group_code or v_batch.start_date <> v_group.scheduled_start_date then
    raise exception 'The Master Batch identity and Day 0 date must match the selected schedule group';
  end if;

  update public.master_batch
     set schedule_group_id = v_group.id,
         config = config || jsonb_build_object('schedule_source', v_group.schedule_import_id::text)
   where id = v_batch.id;

  update public.monthly_schedule_group
     set status = 'instantiated', master_batch_id = v_batch.id,
         instantiated_at = now(), instantiated_by = auth.uid()
   where id = v_group.id;

  insert into public.audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state)
  values (auth.uid(), public.current_app_role(), 'instantiate_scheduled_batch',
          'monthly_schedule_group', v_group.id::text,
          jsonb_build_object('master_batch_id', v_batch.id));
end;
$function$

CREATE OR REPLACE FUNCTION public.clear_planned_time(p_activity uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b master_batch;
begin
  select mb.* into b from master_batch mb
    join batch_activity ba on ba.master_batch_id = mb.id
   where ba.id = p_activity;
  if not found then raise exception 'No such activity'; end if;

  -- The same refusal `set_activity_plan` makes, stated the same way.
  if b.status <> 'draft' then
    raise exception
      'The baseline is frozen - % is %. Change goes through a deviation or an override.',
      b.code, b.status;
  end if;

  update batch_activity set planned_time = null where id = p_activity;
  -- `trg_replan_hours` fires on planned_time and puts the activity back on the standard hour.

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'clear_planned_time', 'batch_activity',
          p_activity::text, 'Returned to the process standard hour');
end;
$function$

CREATE OR REPLACE FUNCTION public.close_machine_stint(p_activity uuid, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba  batch_activity;
  at_ timestamptz;
  n   int;
begin
  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;

  at_ := coalesce(p_at, ba.actual_end, now());
  if at_ > now() then
    raise exception 'A stint cannot end in the future (% is ahead of now)', at_
      using errcode = 'invalid_datetime_format';
  end if;

  update machine_usage mu
     set ended_at = at_, closed_by = auth.uid()
   where mu.batch_activity_id = p_activity and mu.ended_at is null
     and at_ >= mu.started_at;
  get diagnostics n = row_count;

  if n > 0 then
    insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
    values (auth.uid(), public.current_app_role(), 'close_machine_stint', 'batch_activity',
            p_activity::text, 'Machine stint closed on ' || ba.title);
  end if;
  return n;
end;
$function$

CREATE OR REPLACE FUNCTION public.correct_actual(p_activity uuid, p_field text, p_value timestamp with time zone, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba  batch_activity;
  b   master_batch;
  cur timestamptz;
begin
  -- NOT the operator. Correcting the record is a supervisory act, and the person whose work is
  -- late is not the person who should be able to restate when it finished.
  perform public.assert_role(array['supervisor','manager','gm','admin']::app_role[],
                             'correct a recorded actual');

  if p_field not in ('actual_start', 'actual_end') then
    raise exception 'correct_actual handles actual_start and actual_end, not %', p_field
      using errcode = 'invalid_parameter_value';
  end if;

  if coalesce(length(trim(p_reason)), 0) < 10 then
    raise exception
      'A correction needs a reason of at least ten characters. "typo" does not tell anyone reading '
      'this batch in six months what actually happened.'
      using errcode = 'check_violation';
  end if;

  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;

  select * into b from master_batch where id = ba.master_batch_id;

  if p_value is null then
    raise exception 'A correction must state a value. Clearing an actual is not a correction.'
      using errcode = 'invalid_parameter_value';
  end if;
  if p_value > now() then
    raise exception
      'Cannot correct % to %: that is in the future. An actual is something that has already '
      'happened.', ba.title, p_value
      using errcode = 'invalid_datetime_format';
  end if;
  if b.start_at is not null and p_value < b.start_at then
    raise exception
      'Cannot correct % to %: the batch begins at % and nothing in it happens before that.',
      ba.title, p_value, b.start_at
      using errcode = 'invalid_datetime_format';
  end if;

  cur := case when p_field = 'actual_start' then ba.actual_start else ba.actual_end end;
  if cur is null then
    raise exception
      'There is nothing to correct: % has no % recorded. Record it through the normal execution '
      'path instead.', ba.title, p_field
      using errcode = 'check_violation';
  end if;
  if cur = p_value then
    return;                                    -- idempotent; not a correction.
  end if;

  -- Ordering still has to hold after the correction, or a supervisor can produce an activity that
  -- ended before it began by fixing one half of the pair.
  if p_field = 'actual_start' and ba.actual_end is not null and ba.actual_end < p_value then
    raise exception
      'Cannot move the start of % to %: it is already recorded as ending at %, and work does not '
      'end before it begins. Correct the end first.', ba.title, p_value, ba.actual_end
      using errcode = 'invalid_datetime_format';
  end if;
  if p_field = 'actual_end' and ba.actual_start is not null and p_value < ba.actual_start then
    raise exception
      'Cannot move the end of % to %: it is recorded as starting at %, and work does not end '
      'before it begins.', ba.title, p_value, ba.actual_start
      using errcode = 'invalid_datetime_format';
  end if;

  perform set_config('mushroomos.correction_reason', p_reason, true);

  if p_field = 'actual_start' then
    update batch_activity set actual_start = p_value where id = p_activity;
  else
    update batch_activity set actual_end = p_value where id = p_activity;
  end if;

  -- Cleared immediately. Leaving it set would let any LATER update in the same transaction
  -- overwrite a different actual under a reason written for this one.
  perform set_config('mushroomos.correction_reason', '', true);

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'correct_actual', 'batch_activity',
          p_activity::text, p_field || ': ' || p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.create_master_batch(p_code text, p_label text, p_start_date date, p_config jsonb, p_roles jsonb, p_supervisor text DEFAULT NULL::text, p_weather text DEFAULT NULL::text, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_process_definition_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  new_batch uuid;
  def       process_definition;
  r         jsonb;
  h0        timestamptz;
begin
  perform public.assert_role(array['admin', 'gm']::app_role[], 'create a batch');

  -- WHICH STANDARD. Named by the caller, or the catalogue's. Never a literal.
  select * into def from process_definition
   where id = coalesce(p_process_definition_id, public.current_process_definition());

  if def.id is null then
    raise exception
      'No process definition to plan against. Either name one, or set the current standard: '
      'select public.set_current_process(''<definition id>'').'
      using errcode = 'invalid_parameter_value';
  end if;

  if def.status <> 'published' then
    raise exception
      'Cannot plan % against % v% — it is %. A draft standard can still change, and the '
      'baseline this batch freezes would then describe hours nobody stated.',
      p_code, def.code, def.version, def.status
      using errcode = 'check_violation';
  end if;

  -- An explicit H0 wins; otherwise the factory clock decides. `factory_h0_instant` returns
  -- NULL while `factory_clock.timezone` is unset, and a NULL here would recreate the exact
  -- defect 0030 exists to fix — so it is refused loudly, naming the one call that fixes it.
  h0 := coalesce(p_start_at, public.factory_h0_instant(p_start_date));
  if h0 is null then
    raise exception
      'Cannot create %: the factory timezone is not set, so H0 cannot be computed. '
      'Run select public.set_factory_timezone(''<IANA zone>'') once.', p_code
      using errcode = 'invalid_parameter_value';
  end if;

  insert into master_batch (code, label, process_definition_id, start_date, start_at, status,
                            supervisor_name, weather_note, config, created_by)
  values (p_code, p_label, def.id, p_start_date, h0, 'draft', p_supervisor, p_weather,
          p_config, auth.uid())
  returning id into new_batch;

  for r in select * from jsonb_array_elements(p_roles) loop
    insert into batch_material_role (master_batch_id, role, material_id, is_role_lead)
    select new_batch, (r->>'role')::material_role_code, m.id,
           coalesce((r->>'lead')::boolean, false)
    from material m where m.code = r->>'material_code'
    on conflict do nothing;
  end loop;

  perform generate_activity_plan(new_batch);
  return new_batch;
end;
$function$

CREATE OR REPLACE FUNCTION public.custom_access_token_hook(event jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  claims    jsonb;
  user_role text;
begin
  select role::text into user_role
  from public.profiles
  where id = (event->>'user_id')::uuid;

  claims := event->'claims';

  if user_role is not null then
    if claims ? 'app_metadata' then
      claims := jsonb_set(claims, '{app_metadata,app_role}', to_jsonb(user_role));
    else
      claims := jsonb_set(claims, '{app_metadata}', json_build_object('app_role', user_role)::jsonb);
    end if;
  end if;

  return jsonb_set(event, '{claims}', claims);
end;
$function$

CREATE OR REPLACE FUNCTION public.decide_lab_submission(p_activity uuid, p_verdict text, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba      batch_activity;
  role_   app_role;
  reading lab_approval_reading;
  n_en    int;
  new_id  uuid;
  roles   text;
begin
  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;
  if ba.responsible_role is distinct from 'lab_tech' then
    raise exception
      '% is not a lab activity, so this is not a lab submission. A management checkpoint is '
      'decided with record_checkpoint_decision.', ba.title;
  end if;
  if p_verdict not in ('approved','rejected') then
    raise exception 'A lab submission is approved or rejected, not %', p_verdict;
  end if;
  -- MANDATORY, like every other decision reason in this system.
  if p_reason is null or btrim(p_reason) = '' then
    raise exception 'A decision on % needs a stated reason', ba.title;
  end if;

  role_ := public.current_app_role();
  select count(*) into n_en from lab_approval_reading where is_enabled;

  if n_en > 0 then
    -- C-32 has been answered. Only the enabled reading's role may decide.
    select * into reading from lab_approval_reading where is_enabled;
    if role_ is distinct from reading.approver_role then
      raise exception
        'A % may not decide a lab submission. C-32 has been answered as "%": the % approves.',
        coalesce(role_::text, 'caller with no role'), reading.reading_code, reading.approver_role
        using errcode = 'insufficient_privilege';
    end if;
  else
    -- C-32 IS OPEN. Both readings stand, so a decision from either named role is accepted and the
    -- row records which reading authorised it. Refusing both would leave the state unreachable —
    -- exactly the defect B1 found in GM_APPROVAL.
    select * into reading from lab_approval_reading where approver_role = role_ limit 1;
    if not found then
      select string_agg(distinct approver_role::text, ' or ' order by approver_role::text)
        into roles from lab_approval_reading;
      raise exception
        'A % may not decide a lab submission. C-32 is open and neither reading names that role — '
        'the two readings on file name %. Both are carried; neither has been chosen.',
        coalesce(role_::text, 'caller with no role'), coalesce(roles, 'no role')
        using errcode = 'insufficient_privilege';
    end if;
  end if;

  insert into lab_decision (batch_activity_id, verdict, reason, decided_by, decided_role,
                            authorised_under_reading, reading_was_enabled)
  values (p_activity, p_verdict, p_reason, auth.uid(), role_,
          reading.reading_code, reading.is_enabled)
  returning id into new_id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), role_, 'decide_lab_submission', 'batch_activity', p_activity::text,
          jsonb_build_object('verdict', p_verdict, 'under_reading', reading.reading_code,
                             'reading_enabled', reading.is_enabled),
          p_verdict || ': ' || p_reason);
  /*
   * 0065 · THE GATE OPENS THROUGH `advance_batch`, LIKE EVERYTHING ELSE.
   *
   * 0064 was right that the decision had to write the release down, and WRONG about how.
   * It re-evaluated the held activities itself and set their state directly, which made
   * `decide_lab_submission` the tenth writer of `batch_activity.state` — and
   * `gates.test.ts` refused it, in the words of the rule it was defending:
   *
   *     "A new writer of batch_activity.state appeared. Either route it through
   *      advance_batch, or add it to SANCTIONED with the reason it is an actor
   *      transition rather than a gate."
   *
   * It is not an actor transition. Opening a held activity because a gate now passes is exactly
   * what `advance_batch` is for, and `submit_activity` and `release_activity` already delegate
   * to it for precisely this reason. 0064's stated objection — that a lab approval should not
   * release rests batch-wide as a side effect — was mine, not the project's, and the two functions
   * above had already settled the question the other way.
   *
   * So the decision now does what every other actor transition does: it records what it decided,
   * and asks the one gate-driven writer to work out what that opens.
   */
  perform public.advance_batch(ba.master_batch_id);

  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.escalate_deviation(p_deviation uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.assert_role(array['supervisor']::app_role[], 'Escalating a deviation');
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'An escalation needs a reason — the GM is being asked to decide on it';
  end if;

  update deviation
     set state = 'escalated', decided_at = now(), decided_by = auth.uid(),
         decided_by_role = public.current_app_role(), decision_reason = p_reason
   where id = p_deviation and state = 'open';

  if not found then raise exception 'Deviation is not open, or does not exist'; end if;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'escalate_deviation', 'deviation',
          p_deviation::text, p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.evaluate_cardinality(p_rule jsonb, p_config jsonb)
 RETURNS TABLE(instance_no integer, scope_label text, planned_qty_mt numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
begin
  if p_rule->>'kind' = 'FIXED_LABEL' then
    if coalesce(p_rule->>'label', '') = '' then
      raise exception 'A FIXED_LABEL cardinality rule must carry a label.';
    end if;
    return query select 1, p_rule->>'label', null::numeric;
    return;
  end if;
  return query select * from public.evaluate_cardinality_v1(p_rule, p_config);
end;
$function$

CREATE OR REPLACE FUNCTION public.evaluate_cardinality_v1(p_rule jsonb, p_config jsonb)
 RETURNS TABLE(instance_no integer, scope_label text, planned_qty_mt numeric)
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  kind      text := p_rule->>'kind';
  qty       numeric;
  cap       numeric;
  n         int;
  i         int;
  remaining numeric;
  planned   numeric;
  field     text;
  noun      text;
begin
  if kind = 'SINGLETON' then
    return query select 1, 'Whole batch'::text, null::numeric;

  elsif kind = 'DERIVED_FROM_QUANTITY' then
    qty := nullif(p_config->>(p_rule->>'quantity_field'), '')::numeric;
    cap := nullif(p_config->>(p_rule->>'capacity_field'), '')::numeric;
    if qty is null or cap is null or cap <= 0 then
      raise exception 'Missing or invalid Day-0 value: % / %',
        p_rule->>'quantity_field', p_rule->>'capacity_field';
    end if;
    n := ceil(qty / cap);
    remaining := qty;
    for i in 1..n loop
      -- The tail carries the remainder: 21.0 - 10 x 2.0 = 1.0 MT, not another full load.
      planned := round(least(cap, remaining), 3);
      if i = n then planned := round(remaining, 3); end if;
      return query select i, format('Load %s of %s', lpad(i::text, 2, '0'), n), planned;
      remaining := round(remaining - planned, 3);
    end loop;

  elsif kind = 'PER_SCOPE_INSTANCE' then
    field := coalesce(p_rule->>'count_field',
                      public.scope_count_field((p_rule->>'scope')::activity_scope));
    n := nullif(p_config->>field, '')::int;
    if n is null then
      raise exception 'Missing Day-0 value: %', field;
    end if;
    noun := public.scope_noun((p_rule->>'scope')::activity_scope);
    for i in 1..n loop
      return query select i, format('%s %s of %s', noun, i, n), null::numeric;
    end loop;

  elsif kind = 'CREATES_SCOPE_INSTANCES' then
    n := nullif(p_config->>(p_rule->>'count_field'), '')::int;
    if n is null then
      raise exception 'Missing Day-0 value: %', p_rule->>'count_field';
    end if;
    for i in 1..n loop
      return query select i, format('%s-%s', p_rule->>'label_prefix', i), null::numeric;
    end loop;

  elsif kind = 'MERGES_SCOPE_INSTANCES' then
    n := coalesce((p_rule->>'to_count')::int, 1);
    for i in 1..n loop
      return query select i, coalesce(p_rule->>'new_label', 'Merged'), null::numeric;
    end loop;

  elsif kind = 'REPEAT' then
    n := nullif(p_config->>(p_rule->>'count_field'), '')::int;
    if n is null then
      raise exception 'Missing Day-0 value: %', p_rule->>'count_field';
    end if;
    for i in 1..n loop
      return query select i,
        replace(coalesce(p_rule->>'index_label', 'Pass {n}'), '{n}', i::text), null::numeric;
    end loop;

  else
    raise exception 'Unknown cardinality kind: %', kind;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.evaluate_gates(p_activity uuid, p_phase text DEFAULT 'entry'::text)
 RETURNS TABLE(rule_id uuid, kind text, binding text, verdict text, reason text, is_enabled boolean, mapping_confidence text, conflict_id text, ordering integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba        batch_activity;
  g         record;
  sub       jsonb;
  st        record;
  v_ok      boolean;
  v_vars    jsonb;
  v_verdict text;
  v_sub_ok  boolean;
  v_any_ok  boolean;
  v_fld     batch_activity_value;
  v_out_n   int;
  v_out_lbl text;
  v_actual  numeric;
  v_hours   numeric;
  v_remain  interval;
  v_machine text;
  v_stints_exist boolean;
  v_cp      int;
begin
  if p_phase not in ('entry','exit') then
    raise exception 'phase must be entry or exit, got %', p_phase;
  end if;

  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;

  select exists (
    select 1 from information_schema.tables
     where table_schema = 'public' and table_name = 'machine_usage'
  ) into v_stints_exist;

  for g in
    select gr.* from gate_rule gr
    where gr.process_activity_id = ba.process_activity_id
      and gr.phase = p_phase
    order by gr.ordering, gr.id
  loop
    v_vars := jsonb_build_object('scope_label', ba.scope_label);
    v_verdict := null;
    v_ok := null;

    if not g.is_enabled then
      v_verdict := 'skipped';

    elsif g.kind in ('FIELD_IN_RANGE','SENSOR_THRESHOLD')
          and g.mapping_confidence not in ('dictated','sop_direct') then
      v_verdict := 'skipped';

    elsif g.kind = 'PREDECESSOR' then
      select * into st from gate_predecessor_status(
        ba.master_batch_id, ba.instance_no, g.config->'activity_codes', g.predecessor_binding);
      v_ok := st.ok;
      -- 0051 · A rest measured from the PREDECESSOR'S ACTUAL END.
      -- The Turner: 8 h after THAT PILE'S OWN T1 end. Not T0 start + 24 h (F10),
      -- and not ELAPSED_TIME, which measures from this activity's own start.
      v_hours := nullif(g.config->>'min_rest_hr', '')::numeric;

      -- 0062 · The required rest is a property of the RULE, knowable long before anything
      -- finishes. 0051 populated it only inside `if v_ok` — i.e. only once the predecessor was
      -- already complete — so in the ordinary case the card read "rests not recorded h".
      if v_hours is not null then
        v_vars := v_vars || jsonb_build_object(
          -- `FM` strips trailing ZEROS but leaves the decimal POINT, so 8 renders as "8." and the
          -- card reads "rests 8. h". Trim the point too; 7.5 still renders as "7.5".
          'rest_required_hr', trim(trailing '.' from trim(to_char(v_hours, 'FM999990.99'))));

        if not v_ok then
          -- The predecessor has not finished. Say so, instead of a sentence that claims it did.
          v_vars := v_vars || jsonb_build_object(
            'rest_status',
            'That ' || coalesce(st.blocker_title, 'earlier activity') || ' has not finished yet.');

        elsif st.last_actual_end is null then
          -- Complete, but with no recorded end there is nothing to measure from. Refuse:
          -- treating an unknown end as "long enough ago" is how a rest gets skipped.
          v_ok := false;
          v_vars := v_vars || jsonb_build_object(
            'rest_remaining', 'unknown — no finish time recorded',
            'rest_status',
            'It is marked complete but carries no finish time, so the rest cannot be measured. '
            || 'Ask a supervisor to record the finish.');

        else
          v_remain := greatest(
            st.last_actual_end + make_interval(secs => (v_hours * 3600)::int) - now(),
            interval '0');
          v_ok := (v_remain = interval '0');
          v_vars := v_vars || jsonb_build_object(
            'predecessor_ended_at', to_char(st.last_actual_end, 'DD Mon HH24:MI'),
            'rest_remaining',       to_char(v_remain, 'HH24:MI'),
            'rest_status',
              'It finished at ' || to_char(st.last_actual_end, 'DD Mon HH24:MI')
              || ' — ' || to_char(v_remain, 'HH24:MI') || ' still to go.');
        end if;
      end if;

      v_vars := v_vars
        || jsonb_build_object('predecessor_label', st.blocker_title)
        || jsonb_build_object('stream_label',
             case when st.blocker_stream is null then null
                  else initcap(replace(st.blocker_stream, '_', ' ')) end);

    elsif g.kind in ('BOTH','EITHER_OR') then
      v_any_ok := false;
      v_ok := (g.kind = 'BOTH');
      for sub in select * from jsonb_array_elements(coalesce(g.config->'sub', '[]'::jsonb)) loop
        v_sub_ok := null;
        if sub->>'kind' = 'PREDECESSOR' then
          select * into st from gate_predecessor_status(
            ba.master_batch_id, ba.instance_no, sub->'activity_codes', sub->>'binding');
          v_sub_ok := st.ok;
          if not st.ok then
            v_vars := v_vars
              || jsonb_build_object('predecessor_label', st.blocker_title)
              || jsonb_build_object('stream_label',
                   case when st.blocker_stream is null then null
                        else initcap(replace(st.blocker_stream, '_', ' ')) end);
          end if;
        elsif sub->>'kind' = 'ELAPSED_TIME' then
          v_hours := nullif(sub->>'hours','')::numeric;
          v_sub_ok := ba.actual_start is not null and v_hours is not null
                      and now() >= ba.actual_start + make_interval(secs => (v_hours * 3600)::int);
        else
          v_sub_ok := null;
        end if;

        if g.kind = 'BOTH' then
          if v_sub_ok is false then v_ok := false; end if;
        elsif v_sub_ok is true then
          v_any_ok := true;
        end if;
      end loop;

      if g.kind = 'EITHER_OR' then v_ok := v_any_ok; end if;

    elsif g.kind = 'DAY0_DURATION' then
      if ba.day0_duration_hr is null then
        v_ok := false;
        v_vars := v_vars || jsonb_build_object(
          'required', 'not set' || coalesce(' (' || ba.tbd_marker || ')', ''),
          'remaining', 'unknown');
      elsif ba.unblocks_at is null then
        v_ok := false;
        v_remain := make_interval(secs => (ba.day0_duration_hr * 3600)::int);
        v_vars := v_vars || jsonb_build_object(
          'required', to_char(v_remain, 'HH24:MI'), 'remaining', 'not started');
      else
        v_ok := now() >= ba.unblocks_at;
        v_remain := greatest(ba.unblocks_at - now(), interval '0');
        v_vars := v_vars || jsonb_build_object(
          'required', to_char(make_interval(secs => (ba.day0_duration_hr * 3600)::int), 'HH24:MI'),
          'remaining', to_char(v_remain, 'HH24:MI'));
      end if;

    elsif g.kind = 'ELAPSED_TIME' then
      v_hours := nullif(g.config->>'hours','')::numeric;
      v_ok := ba.actual_start is not null and v_hours is not null
              and now() >= ba.actual_start + make_interval(secs => (v_hours * 3600)::int);
      v_vars := v_vars || jsonb_build_object(
        'elapsed', case when ba.actual_start is null then 'not started'
                        else round(extract(epoch from (now() - ba.actual_start)) / 3600, 1)::text end);

    elsif g.kind = 'EVIDENCE_COMPLETE' then
      select count(*)::int, string_agg(r.label, ', ' order by r.ordering)
        into v_out_n, v_out_lbl
      from batch_activity_evidence_req r
      where r.batch_activity_id = ba.id
        and r.gates_submission and r.satisfied_count < r.min_count;
      v_ok := coalesce(v_out_n, 0) = 0;
      v_vars := v_vars || jsonb_build_object(
        'outstanding_count', coalesce(v_out_n, 0)::text, 'outstanding_labels', v_out_lbl);

    elsif g.kind = 'FIELD_IN_RANGE' then
      select * into v_fld from batch_activity_value
       where batch_activity_id = ba.id and field_key = g.config->>'field_key';

      if not found or v_fld.actual_value is null
         or v_fld.actual_value !~ '^-?[0-9]+(\.[0-9]+)?$' then
        v_verdict := 'unevaluable';
        v_vars := v_vars || jsonb_build_object('actual', 'not recorded');
      else
        v_actual := v_fld.actual_value::numeric;
        v_ok := (v_fld.sop_min is null or v_actual >= v_fld.sop_min)
            and (v_fld.sop_max is null or v_actual <= v_fld.sop_max);
        v_vars := v_vars || jsonb_build_object(
          'actual', v_fld.actual_value,
          'min', coalesce(v_fld.sop_min::text, '—'),
          'max', coalesce(v_fld.sop_max::text, '—'));
      end if;

    elsif g.kind = 'MACHINE_STINT_CLOSED' then
      select m.code into v_machine from machine m where m.id = ba.assigned_machine_id;
      v_vars := v_vars || jsonb_build_object('machine_code', v_machine);

      if v_stints_exist then
        execute 'select not exists (select 1 from public.machine_usage mu'
                || ' where mu.batch_activity_id = $1 and mu.ended_at is null)'
          into v_ok using ba.id;
      else
        v_ok := true;
      end if;

    elsif g.kind = 'LAB_APPROVED' then
      -- 0054 · ENTERED IS NOT APPROVED.
      --
      -- Which laboratory activities are bound to hold THIS one, and has the latest decision
      -- on each of them approved it? `lab_checkpoint_activity` carries the pairing, so a
      -- per-bunker gate waits on its own bunker's assay and not on all three.
      --
      -- A REJECTED or ABSENT decision does not open the gate. Neither does a recorded
      -- result: a reading that nobody has approved is a reading, not an approval.
      select count(*)::int,
             count(*) filter (where lab.verdict = 'approved')::int,
             string_agg(distinct lab.checkpoint_code, ', ')
        into v_out_n, v_cp, v_out_lbl
      from (
        select lca.checkpoint_code,
               (select d.verdict from lab_decision d
                 where d.batch_activity_id = lba.id
                 order by d.seq desc limit 1) as verdict
          from batch_activity lba
          join lab_checkpoint_activity lca on lca.process_activity_id = lba.process_activity_id
          join lab_checkpoint cp on cp.checkpoint_map = lca.checkpoint_map
                                and cp.code = lca.checkpoint_code
         where lba.master_batch_id = ba.master_batch_id
           and lca.gates_activity_code = ba.code
           and cp.kind = 'GATE'
      ) lab;

      if coalesce(v_out_n, 0) = 0 then
        -- A gate rule with nothing bound to it cannot be evaluated. Passing would silently
        -- open production; failing would lock it for ever with no way to clear it. Say so.
        v_verdict := 'unevaluable';
        v_vars := v_vars || jsonb_build_object(
          'checkpoint', 'no laboratory checkpoint is bound to this activity');
      else
        v_ok := (v_cp = v_out_n);
        v_vars := v_vars || jsonb_build_object(
          'checkpoint', coalesce(v_out_lbl, '?'),
          'approved_count', v_cp::text,
          'required_count', v_out_n::text);
      end if;

    elsif g.kind = 'GM_APPROVAL' then
      -- ── B6 · CHANGED FROM 0012's `v_ok := false`. ─────────────────────────
      -- The checkpoint number is the RULE's, not this function's: `s04` seeds `'{"checkpoint":3}'`
      -- on TN-LOAD, so which checkpoint gates which activity stays data.
      --
      -- `returned` does NOT open the gate. Only an approval does, and `approved_with_conditions` is
      -- an approval — §5 puts it beside APPROVE on the screen, and the conditions live in the
      -- mandatory reason, which the snapshot preserves.
      --
      -- The LATEST decision governs. A batch approved, returned, then approved again is at its third
      -- decision, and the first two stay on the record.
      v_cp := nullif(g.config->>'checkpoint','')::int;

      if v_cp is null then
        -- An approval rule that does not say WHICH checkpoint cannot be evaluated, and guessing at
        -- one would be inventing the process's own structure.
        v_verdict := 'unevaluable';
        v_vars := v_vars || jsonb_build_object('checkpoint', 'not stated on the rule');
      else
        v_ok := exists (
          select 1 from public.v_checkpoint_status s
           where s.master_batch_id = ba.master_batch_id
             and s.checkpoint_no = v_cp
             and s.latest_verdict in ('approved','approved_with_conditions'));
        v_vars := v_vars || jsonb_build_object('checkpoint', v_cp::text);
      end if;

    else
      v_verdict := 'unevaluable';
    end if;

    if v_verdict is null then
      v_verdict := case when v_ok then 'pass' when v_ok is null then 'unevaluable' else 'fail' end;
    end if;

    return query select
      g.id,
      g.kind,
      g.predecessor_binding,
      v_verdict,
      case when v_verdict = 'fail' then render_gate_reason(g.blocked_reason_template, v_vars) end,
      g.is_enabled,
      g.mapping_confidence,
      g.conflict_id,
      g.ordering;
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.evidence_path_is_consistent(p_batch text, p_activity text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b uuid;
  a uuid;
begin
  -- A path segment is text and may be anything at all. A bad cast is a refusal, not an error.
  begin
    b := p_batch::uuid;
    a := p_activity::uuid;
  exception when others then
    return false;
  end;
  return exists (
    select 1 from batch_activity ba
     where ba.id = a and ba.master_batch_id = b);
end;
$function$

CREATE OR REPLACE FUNCTION public.expire_extensions()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  pol extension_policy;
  n int := 0;
begin
  select * into pol from extension_policy where extension_policy.id;
  -- NULL means a request waits forever, which is the honest default: silently
  -- expiring a request nobody answered would lose the fact that nobody answered.
  if pol.request_expiry_hr is null then return 0; end if;

  update extension_request set status = 'EXPIRED', expired_at = now()
   where status in ('REQUESTED','MANAGER_APPROVED')
     and requested_at < now() - make_interval(secs => (pol.request_expiry_hr * 3600)::int);
  get diagnostics n = row_count;
  return n;
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_h0_instant(p_start_date date)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare fc public.factory_clock;
begin
  if p_start_date is null then return null; end if;

  select * into fc from public.factory_clock where id = 1;

  -- TBD-50. Returning anything here would adopt the server's zone, and a five-hour day boundary
  -- silently moving is the whole point of TIME_CONTRACT §3.2. NULL is the honest answer.
  if not found or fc.timezone is null then
    return null;
  end if;

  return (p_start_date + make_time(fc.h0_hour_of_day, fc.h0_minute_of_hour, 0))
         at time zone fc.timezone;
end;
$function$

CREATE OR REPLACE FUNCTION public.factory_instant(p_date date, p_time time without time zone)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare tz text;
begin
  if p_date is null or p_time is null then return null; end if;

  select timezone into tz from factory_clock where id = 1;
  if tz is null then
    -- The same refusal `factory_h0_instant` makes: no zone means no wall clock, and guessing one
    -- would place the batch against the wrong day boundary for its whole life.
    return null;
  end if;

  return (p_date + p_time) at time zone tz;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_actual_is_append_only()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  reason text := nullif(trim(coalesce(current_setting('mushroomos.correction_reason', true), '')), '');
  f      text;
  oldv   timestamptz;
  newv   timestamptz;
begin
  foreach f in array array['actual_start', 'actual_end'] loop
    if f = 'actual_start' then
      oldv := old.actual_start; newv := new.actual_start;
    else
      oldv := old.actual_end;   newv := new.actual_end;
    end if;

    -- Unchanged, or being set for the first time. Normal execution.
    if oldv is null or newv is not distinct from oldv then
      continue;
    end if;

    -- There is no "un-happen".
    if newv is null then
      raise exception
        'Cannot clear %.% on %: an actual that has been recorded cannot become unknown. If it was '
        'recorded in error, correct it to the right value with correct_actual and state why.',
        'batch_activity', f, old.title
        using errcode = 'check_violation';
    end if;

    if reason is null then
      raise exception
        'Refusing to overwrite %.% on % (% -> %). An actual that has been recorded is history. '
        'To change it, call correct_actual(activity, ''%'', new_value, reason) — the original is '
        'kept and the correction names who made it and why.',
        'batch_activity', f, old.title, oldv, newv, f
        using errcode = 'check_violation';
    end if;

    insert into actual_correction
      (batch_activity_id, master_batch_id, field, previous_value, new_value,
       reason, corrected_by, corrected_role)
    values
      (old.id, old.master_batch_id, f, oldv, newv,
       reason, auth.uid(), public.current_app_role());
  end loop;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_audit_plan_generated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare n int;
begin
  select count(*) into n from batch_activity where master_batch_id = new.id;
  if n > 0 then
    insert into audit_event (actor_id, actor_role, action, entity_table, entity_id,
                             after_state, reason)
    values (auth.uid(), public.current_app_role(), 'plan_generated', 'master_batch',
            new.id::text,
            jsonb_build_object('activities', n, 'config', new.config),
            format('%s activities generated from the Day-0 configuration', n));
  end if;
  return null;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_definition_is_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  st process_status;
  cd text;
  vn int;
begin
  -- An update that changes nothing is not a change. `is distinct from` on the whole row, which is
  -- the same test `fn_audit` applies before deciding whether anything happened worth recording.
  if tg_op = 'UPDATE' and new is not distinct from old then
    return new;
  end if;

  select status, code, version into st, cd, vn
    from public.process_definition
   where id = coalesce(new.process_definition_id, old.process_definition_id);

  if st = 'published' then
    raise exception
      '% v% is published — its activities are frozen. A batch has been, or will be, planned '
      'against exactly these hours. Publish a new version instead of editing this one.', cd, vn
      using errcode = 'check_violation';
  end if;
  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_factory_clock_validate()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if new.timezone is not null
     and not exists (select 1 from pg_timezone_names where name = new.timezone) then
    raise exception '% is not an IANA timezone name', new.timezone
      using hint = 'select name from pg_timezone_names';
  end if;
  new.updated_at := now();
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_gate_rule_protection()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare code text;
begin
  select pa.code into code from process_activity pa where pa.id = new.process_activity_id;
  -- Unconditional. The caller's value is not consulted, because a caller that could pass `false`
  -- here is exactly how the flag went missing in the first place.
  new.is_protected := public.gate_rule_is_protected(code, new.kind::text, new.config);
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_inherit_hold()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  if new.is_hold is not distinct from false then
    select coalesce(pa.is_hold, false) into new.is_hold
      from public.process_activity pa where pa.id = new.process_activity_id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_new_table_is_read_only()
 RETURNS event_trigger
 LANGUAGE plpgsql
AS $function$
declare
  obj record;
begin
  for obj in
    select * from pg_event_trigger_ddl_commands()
     where command_tag = 'CREATE TABLE' and schema_name = 'public' and object_type = 'table'
  loop
    execute format('revoke all on %s from anon, public', obj.object_identity);
    execute format('revoke insert, update, delete, truncate, references on %s from authenticated', obj.object_identity);
    execute format('grant select on %s to authenticated', obj.object_identity);
  end loop;
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_plan_is_frozen()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
declare
  st   batch_status;
  code text;
  moved text[] := '{}';
begin
  if new.planned_start_at    is not distinct from old.planned_start_at
 and new.planned_end_at      is not distinct from old.planned_end_at
 and new.baseline_start_hour is not distinct from old.baseline_start_hour
 and new.baseline_end_hour   is not distinct from old.baseline_end_hour
 and new.planned_time        is not distinct from old.planned_time
 and new.day0_duration_hr    is not distinct from old.day0_duration_hr
  then
    return new;                       -- the Plan register did not move
  end if;

  select mb.status, mb.code into st, code
    from master_batch mb where mb.id = old.master_batch_id;

  if st = 'draft' then
    return new;                       -- still being written; that is what draft is for
  end if;

  -- Name the columns that moved. A refusal an engineer cannot act on is half a
  -- refusal, and this one will most often be read from a server log.
  if new.planned_start_at    is distinct from old.planned_start_at    then moved := moved || 'planned_start_at'::text; end if;
  if new.planned_end_at      is distinct from old.planned_end_at      then moved := moved || 'planned_end_at'::text; end if;
  if new.baseline_start_hour is distinct from old.baseline_start_hour then moved := moved || 'baseline_start_hour'::text; end if;
  if new.baseline_end_hour   is distinct from old.baseline_end_hour   then moved := moved || 'baseline_end_hour'::text; end if;
  if new.planned_time        is distinct from old.planned_time        then moved := moved || 'planned_time'::text; end if;
  if new.day0_duration_hr    is distinct from old.day0_duration_hr    then moved := moved || 'day0_duration_hr'::text; end if;

  raise exception
    'The baseline of % is frozen (batch is %). Refused a change to %. The plan of an activated batch is evidence, not a working document - record what happened, or request an authorised extension.',
    code, st, array_to_string(moved, ', ')
    using errcode = 'check_violation';
end;
$function$

CREATE OR REPLACE FUNCTION public.fn_track_occupancy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  pa   process_activity;
  alloc batch_vessel_allocation;
  excl boolean;
begin
  select * into pa from process_activity where id = new.process_activity_id;
  if not found or pa.scope is null then return new; end if;

  select * into alloc from batch_vessel_allocation
   where master_batch_id = new.master_batch_id
     and scope = pa.scope::text
     and instance_no = new.instance_no;
  if not found then return new; end if;          -- unallocated slot: record nothing, invent nothing

  -- WORK STARTED → the vessel is occupied from the recorded start, not from `now()`. An actual
  -- start backdated by an operator has to place the batch when it was actually there.
  if new.actual_start is not null and (old.actual_start is null) then
    select l.is_exclusive into excl from location l where l.id = alloc.location_id;
    insert into location_occupancy
      (location_id, master_batch_id, batch_activity_id, stream, started_at, is_exclusive, tbd_marker)
    values (alloc.location_id, new.master_batch_id, new.id, new.stream, new.actual_start,
            coalesce(excl, true), alloc.conflict_id)
    on conflict do nothing;
  end if;

  -- WORK FINISHED → close the window. `ended_at` is the recorded end for the same reason.
  if new.actual_end is not null and (old.actual_end is null) then
    update location_occupancy
       set ended_at = new.actual_end
     where batch_activity_id = new.id
       and ended_at is null;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gate_predecessor_status(p_batch uuid, p_instance_no integer, p_codes jsonb, p_binding text)
 RETURNS TABLE(ok boolean, blocker_title text, blocker_stream text, total integer, done integer, last_actual_end timestamp with time zone)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_total   int := 0;
  v_done    int := 0;
  v_title   text;
  v_stream  text;
  v_end     timestamptz;
  v_binding text := coalesce(p_binding, 'ALL_INSTANCES');
begin
  if p_codes is null or jsonb_typeof(p_codes) <> 'array' or jsonb_array_length(p_codes) = 0 then
    return query select true, null::text, null::text, 0, 0, null::timestamptz;
    return;
  end if;

  select count(*)::int,
         count(*) filter (where ba.state in ('COMPLETED','SKIPPED'))::int,
         max(ba.actual_end)
    into v_total, v_done, v_end
  from batch_activity ba
  where ba.master_batch_id = p_batch
    and ba.code in (select jsonb_array_elements_text(p_codes))
    and (v_binding <> 'SAME_SCOPE_INSTANCE' or ba.instance_no = p_instance_no);

  if v_total = 0 then
    return query select true, null::text, null::text, 0, 0, null::timestamptz;
    return;
  end if;

  -- Name the instance that is actually holding this up, not an arbitrary one.
  select ba.title, ba.stream::text into v_title, v_stream
  from batch_activity ba
  where ba.master_batch_id = p_batch
    and ba.code in (select jsonb_array_elements_text(p_codes))
    and (v_binding <> 'SAME_SCOPE_INSTANCE' or ba.instance_no = p_instance_no)
    and ba.state not in ('COMPLETED','SKIPPED')
  order by ba.instance_no
  limit 1;

  if v_binding = 'ANY_INSTANCE' then
    return query select v_done > 0, v_title, v_stream, v_total, v_done, v_end;
  else
    return query select v_done = v_total, v_title, v_stream, v_total, v_done, v_end;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.get_effective_now()
 RETURNS TABLE(dev_available boolean, dev_enabled boolean, is_playing boolean, effective_now timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare c public.dev_effective_clock;
begin
  select * into c from public.dev_effective_clock where id = true;

  if not public.dev_environment_enabled() then
    return query select false, false, false, clock_timestamp(), clock_timestamp();
    return;
  end if;

  if c.id is null then
    return query select false, false, false, clock_timestamp(), clock_timestamp();
    return;
  end if;

  return query
  select true,
         c.enabled,
         c.is_playing,
         case when c.enabled and c.is_playing
              then c.effective_now + (clock_timestamp() - c.updated_at)
              when c.enabled then c.effective_now
              else clock_timestamp()
         end,
         c.updated_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.gm_decide_extension(p_request uuid, p_approve boolean, p_reason text, p_granted_hr numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  er  extension_request;
  pol extension_policy;
  ceiling numeric;
  granted numeric;
begin
  perform public.assert_role(array['gm']::app_role[], 'Deciding an extension as GM');

  select * into pol from extension_policy where extension_policy.id;
  select * into er from extension_request where id = p_request for update;
  if not found then raise exception 'No such extension request: %', p_request; end if;

  if pol.strict_approval_order and pol.manager_approval_required then
    if er.status <> 'MANAGER_APPROVED' then
      raise exception
        'Extension request is % — the manager decides first (extension_policy.strict_approval_order)',
        er.status;
    end if;
  elsif er.status not in ('REQUESTED','MANAGER_APPROVED') then
    raise exception 'Extension request is % — it is already decided', er.status;
  end if;

  if coalesce(trim(p_reason), '') = '' then
    raise exception 'A decision needs a reason';
  end if;

  -- The GM cannot exceed what the manager allowed, and neither can exceed what
  -- was asked for. Approval only ever narrows.
  ceiling := least(coalesce(er.manager_granted_hr, er.requested_extension_hr),
                   er.requested_extension_hr);
  granted := coalesce(p_granted_hr, ceiling);
  if granted > ceiling then
    raise exception 'The GM may approve at most % hours here', ceiling;
  end if;
  if granted <= 0 then
    raise exception 'An approved extension must be a positive number of hours';
  end if;

  if not p_approve then
    update extension_request set
      gm_decision = 'rejected', gm_decided_by = auth.uid(),
      gm_decided_at = now(), gm_reason = trim(p_reason),
      status = 'GM_REJECTED'
    where id = p_request;
  else
    update extension_request set
      gm_decision = 'approved', gm_decided_by = auth.uid(),
      gm_decided_at = now(), gm_reason = trim(p_reason),
      gm_granted_hr = granted
    where id = p_request;
    perform public.fn_make_extension_effective(p_request, granted);
  end if;

  insert into notification (master_batch_id, batch_activity_id, to_role, kind, message, reason, sent_by)
  values (er.master_batch_id, er.batch_activity_id, er.requested_by_role, 'alert',
          format('Extension %s by GM', case when p_approve then 'approved' else 'rejected' end),
          trim(p_reason), auth.uid());

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'gm_decide_extension', 'extension_request',
          p_request::text,
          jsonb_build_object('approve', p_approve, 'granted_hr', case when p_approve then granted end),
          trim(p_reason));
end;
$function$

CREATE OR REPLACE FUNCTION public.gm_decide_override(p_deviation uuid, p_approve boolean, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.assert_role(array['gm']::app_role[], 'Deciding a controlled override');
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'An override decision needs a reason';
  end if;

  update deviation
     set state = case when p_approve then 'accepted'::deviation_state
                      else 'open'::deviation_state end,
         decided_at = now(), decided_by = auth.uid(),
         decided_by_role = public.current_app_role(),
         decision_reason = p_reason
   where id = p_deviation and state = 'escalated';

  if not found then raise exception 'Deviation is not escalated, or does not exist'; end if;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(),
          case when p_approve then 'gm_override_approved' else 'gm_override_refused' end,
          'deviation', p_deviation::text, p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.hold_activity(p_activity uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  perform public.assert_role(array['supervisor']::app_role[], 'Holding an activity');
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'A hold needs a reason — the card has to say why on its face';
  end if;

  update batch_activity
     set state = 'BLOCKED', blocked_reason = 'Held by supervisor — ' || p_reason
   where id = p_activity;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'hold_activity', 'batch_activity',
          p_activity::text, p_reason);
end;
$function$

CREATE OR REPLACE FUNCTION public.hour_within_batch_day(p_start_at timestamp with time zone, p_planned time without time zone)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  tz   text;
  h0   time;
  diff numeric;
begin
  if p_start_at is null or p_planned is null then return null; end if;

  select timezone into tz from factory_clock where id = 1;
  if tz is null then
    -- No zone means no wall clock. Refuse rather than fall back to the server's zone, which would
    -- silently place every batch against the wrong day boundary.
    raise exception
      'The factory timezone is not set, so a planned time of day cannot be placed on the batch '
      'clock. Run set_factory_timezone once.'
      using errcode = 'invalid_parameter_value';
  end if;

  h0 := (p_start_at at time zone tz)::time;
  diff := (extract(epoch from p_planned) - extract(epoch from h0)) / 3600.0;
  -- Wrap into [0, 24). `mod` on a negative gives a negative in Postgres, hence the +24.
  return ((diff::numeric % 24) + 24) % 24;
end;
$function$

CREATE OR REPLACE FUNCTION public.import_monthly_schedule(p_schedule_month date, p_source_filename text, p_column_map jsonb, p_rows jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_import_id uuid;
  v_count integer;
begin
  if auth.uid() is null or not public.has_role('admin') then
    raise exception 'Monthly schedules may only be imported by an Admin';
  end if;
  if p_schedule_month is null
     or p_schedule_month <> date_trunc('month', p_schedule_month)::date then
    raise exception 'Choose the first day of the schedule month';
  end if;
  if jsonb_typeof(p_rows) is distinct from 'array'
     or jsonb_array_length(p_rows) = 0 then
    raise exception 'The spreadsheet contains no scheduled batch groups';
  end if;
  if jsonb_array_length(p_rows) > 2000 then
    raise exception 'A monthly schedule may contain at most 2,000 groups';
  end if;

  -- Validate before changing the current import, so a bad file cannot erase a good schedule.
  select count(*) into v_count
  from jsonb_to_recordset(p_rows) as r(
    source_row_number integer,
    group_code text,
    group_label text,
    scheduled_start_date date,
    resource_note text,
    raw_row jsonb
  )
  where r.source_row_number is null
     or nullif(trim(r.group_code), '') is null
     or r.scheduled_start_date is null
     or date_trunc('month', r.scheduled_start_date)::date <> p_schedule_month;

  if v_count > 0 then
    raise exception 'Every group needs a batch number and a start date inside the selected month';
  end if;

  update public.monthly_schedule_import
     set is_current = false
   where schedule_month = p_schedule_month and is_current;

  insert into public.monthly_schedule_import
    (schedule_month, source_filename, imported_by, source_rows, column_map)
  values
    (p_schedule_month, trim(p_source_filename), auth.uid(), jsonb_array_length(p_rows),
     coalesce(p_column_map, '{}'::jsonb))
  returning id into v_import_id;

  insert into public.monthly_schedule_group
    (schedule_import_id, source_row_number, group_code, group_label, scheduled_start_date,
     resource_note, raw_row)
  select v_import_id, r.source_row_number, trim(r.group_code), nullif(trim(r.group_label), ''),
         r.scheduled_start_date, nullif(trim(r.resource_note), ''), coalesce(r.raw_row, '{}'::jsonb)
  from jsonb_to_recordset(p_rows) as r(
    source_row_number integer,
    group_code text,
    group_label text,
    scheduled_start_date date,
    resource_note text,
    raw_row jsonb
  );

  insert into public.audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state)
  values (auth.uid(), public.current_app_role(), 'import_monthly_schedule',
          'monthly_schedule_import', v_import_id::text,
          jsonb_build_object('schedule_month', p_schedule_month, 'source_rows', jsonb_array_length(p_rows)));

  return v_import_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.manager_decide_extension(p_request uuid, p_approve boolean, p_reason text, p_granted_hr numeric DEFAULT NULL::numeric)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  er  extension_request;
  pol extension_policy;
  granted numeric;
begin
  perform public.assert_role(array['manager']::app_role[], 'Deciding an extension as manager');

  select * into pol from extension_policy where extension_policy.id;
  select * into er from extension_request where id = p_request for update;
  if not found then raise exception 'No such extension request: %', p_request; end if;

  if er.status <> 'REQUESTED' then
    raise exception 'Extension request is % — only a REQUESTED one awaits a manager', er.status;
  end if;
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'A decision needs a reason';
  end if;

  -- A manager may grant LESS than was asked for, never more: approving more time
  -- than anyone requested is a decision nobody made.
  granted := coalesce(p_granted_hr, er.requested_extension_hr);
  if granted > er.requested_extension_hr then
    raise exception 'A manager may approve at most the % hours requested', er.requested_extension_hr;
  end if;
  if granted <= 0 then
    raise exception 'An approved extension must be a positive number of hours';
  end if;

  if not p_approve then
    update extension_request set
      manager_decision = 'rejected', manager_decided_by = auth.uid(),
      manager_decided_at = now(), manager_reason = trim(p_reason),
      status = 'MANAGER_REJECTED'
    where id = p_request;
  else
    update extension_request set
      manager_decision = 'approved', manager_decided_by = auth.uid(),
      manager_decided_at = now(), manager_reason = trim(p_reason),
      manager_granted_hr = granted,
      status = 'MANAGER_APPROVED'
    where id = p_request;

    -- If the policy does not require the GM, the manager's yes was the last one
    -- needed and the authorisation takes effect now.
    if not pol.gm_approval_required then
      perform public.fn_make_extension_effective(p_request, granted);
    end if;
  end if;

  insert into notification (master_batch_id, batch_activity_id, to_role, kind, message, reason, sent_by)
  values (er.master_batch_id, er.batch_activity_id,
          case when p_approve and pol.gm_approval_required then 'gm' else er.requested_by_role end,
          'alert',
          format('Extension %s by manager', case when p_approve then 'approved' else 'rejected' end),
          trim(p_reason), auth.uid());

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'manager_decide_extension', 'extension_request',
          p_request::text,
          jsonb_build_object('approve', p_approve, 'granted_hr', case when p_approve then granted end),
          trim(p_reason));
end;
$function$

CREATE OR REPLACE FUNCTION public.open_machine_stint(p_activity uuid, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba   batch_activity;
  m    machine;
  at_  timestamptz;
  new_id uuid;
  clash  record;
begin
  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;
  if ba.assigned_machine_id is null then
    raise exception '% has no machine assigned, so there is no stint to open', ba.title;
  end if;
  select * into m from machine where id = ba.assigned_machine_id;

  -- Same rule as a recorded actual: not in the future, not before H0. Consistent with 0016/0017
  -- rather than a second opinion about time.
  at_ := coalesce(p_at, ba.actual_start, now());
  if at_ > now() then
    raise exception 'A stint cannot start in the future (% is ahead of now)', at_
      using errcode = 'invalid_datetime_format';
  end if;

  begin
    insert into machine_usage (machine_id, master_batch_id, batch_activity_id, started_at, opened_by)
    values (m.id, ba.master_batch_id, ba.id, at_, auth.uid())
    returning id into new_id;
  exception when exclusion_violation then
    -- The constraint refused. Name the other commitment so the message is actionable.
    select mu.id, other.title, other.scope_label, mu.started_at, mu.ended_at
      into clash
      from machine_usage mu
      join batch_activity other on other.id = mu.batch_activity_id
     where mu.machine_id = m.id and mu.during && tstzrange(at_, null)
     order by mu.started_at limit 1;
    raise exception
      '% is already committed to % (%) %. One machine cannot be in two places at once.',
      m.code, clash.title, clash.scope_label,
      case when clash.ended_at is null
           then 'from ' || clash.started_at || ' onwards, still open'
           else 'from ' || clash.started_at || ' to ' || clash.ended_at end
      using errcode = 'exclusion_violation';
  end;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'open_machine_stint', 'machine_usage', new_id::text,
          jsonb_build_object('machine', m.code, 'activity', ba.title, 'started_at', at_),
          m.code || ' started on ' || ba.title);
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.open_prebatch_sample(p_batch uuid, p_checkpoint uuid, p_label text DEFAULT NULL::text, p_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b      master_batch;
  cp     lab_checkpoint;
  at_    timestamptz;
  new_id uuid;
begin
  select * into b from master_batch where id = p_batch;
  if not found then raise exception 'No such batch: %', p_batch; end if;

  -- A PREREQUISITE, so it belongs before activation. Once the batch is running, the material it
  -- was made from is no longer a question the batch can answer.
  if b.status <> 'draft' then
    raise exception
      'Batch % is %, so an incoming-material check can no longer be recorded against it. The check '
      'is a prerequisite for activation.', b.code, b.status
      using errcode = 'invalid_parameter_value';
  end if;

  select * into cp from lab_checkpoint where id = p_checkpoint;
  if not found then raise exception 'No such lab checkpoint: %', p_checkpoint; end if;
  if not cp.is_prebatch then
    raise exception
      '% is not a pre-batch checkpoint, so it cannot be sampled before the batch starts. Use '
      'open_lab_sample against a running activity instead.', cp.code
      using errcode = 'invalid_parameter_value';
  end if;

  -- NOT BOUNDED BELOW BY H0, and that is the whole point of this function. The only rule is that a
  -- sample cannot have been collected in the future.
  at_ := coalesce(p_at, now());
  if at_ > now() then
    raise exception 'A sample cannot be collected in the future (% is ahead of now)', at_
      using errcode = 'invalid_datetime_format';
  end if;

  insert into lab_sample (checkpoint_id, master_batch_id, batch_activity_id, sample_ref_label,
                          collected_at, collected_by)
  values (cp.id, b.id, null, p_label, at_, auth.uid())
  returning id into new_id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'open_prebatch_sample', 'lab_sample', new_id::text,
          jsonb_build_object('checkpoint', cp.code, 'map', cp.checkpoint_map, 'batch', b.code,
                             'collected_at', at_),
          'Incoming material sampled at ' || cp.code || ' for ' || b.code || ', before H0');
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.order_retest(p_test uuid, p_reason lab_retest_reason, p_numeric numeric DEFAULT NULL::numeric, p_text text DEFAULT NULL::text, p_instrument uuid DEFAULT NULL::uuid, p_invalid_reason text DEFAULT NULL::text, p_measured_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t        lab_test;
  head     lab_result;
  inst     lab_instrument;
  cal      lab_calibration_status := 'unknown';
  at_      timestamptz;
  new_id   uuid;
  n_prior  int;
  escalate int;
begin
  select * into t from lab_test where id = p_test;
  if not found then raise exception 'No such lab test: %', p_test; end if;

  select * into head from lab_result
   where test_id = p_test and superseded_by_result_id is null;
  if not found then
    raise exception
      'There is nothing to retest — no result has been recorded for this test yet.'
      using errcode = 'no_data_found';
  end if;

  -- ROLE. `ROLE_AND_APPROVAL_MODEL` ticks "Order retest" for Lab and Supervisor and nobody else,
  -- and `LAB_MODEL §5` says why: "An operator cannot make a failing number go away."
  if public.current_app_role() is not null
     and public.current_app_role() not in ('lab_tech','supervisor') then
    raise exception
      'A % may not order a retest. ROLE_AND_APPROVAL_MODEL ticks this for the lab technician and '
      'the supervisor only — an operator cannot make a failing number go away.',
      public.current_app_role()
      using errcode = 'insufficient_privilege';
  end if;

  at_ := coalesce(p_measured_at, now());
  if at_ > now() then
    raise exception 'A measurement cannot be recorded in the future (% is ahead of now)', at_
      using errcode = 'invalid_datetime_format';
  end if;

  if p_instrument is not null then
    select * into inst from lab_instrument where id = p_instrument;
    if not found then raise exception 'No such instrument: %', p_instrument; end if;
    if inst.last_calibrated_on is null or inst.calibration_interval_days is null then
      cal := 'unknown';
    elsif inst.last_calibrated_on + inst.calibration_interval_days >= current_date then
      cal := 'valid';
    else
      cal := 'expired';
    end if;
  end if;

  -- ⚠ ORDER MATTERS. `uq_lab_result_one_head` is a partial unique index, checked at the end of
  -- every statement and impossible to defer, so the outgoing head must be demoted BEFORE the new
  -- one is inserted. That means knowing the new id first, and pointing at a row that does not exist
  -- yet — which is why `lab_result_superseded_fk` is DEFERRABLE INITIALLY DEFERRED.
  new_id := gen_random_uuid();

  -- The original is PRESERVED and pointed forward. It is never deleted and never hidden.
  update lab_result set superseded_by_result_id = new_id where id = head.id;

  -- The new version carries the SAME frozen band as the original. That is the point of freezing:
  -- v1 and v2 are comparable because they were judged against one band.
  insert into lab_result (id, test_id, version, value_numeric, value_text, unit,
                          target_min, target_max, invalid_reason, measured_at, technician_id,
                          instrument_id, calibration_status, calibrated_on,
                          retest_reason, supersedes_result_id)
  values (new_id, t.id, head.version + 1, p_numeric, p_text, t.target_unit,
          t.target_min, t.target_max, p_invalid_reason, at_, auth.uid(),
          p_instrument, cal, inst.last_calibrated_on, p_reason, head.id);

  select count(*) into n_prior from lab_result where test_id = p_test and version > 1;
  select int_value into escalate from lab_setting where key = 'retest_escalation_above';

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'order_retest', 'lab_result', new_id::text,
          jsonb_build_object('parameter', t.parameter_code, 'version', head.version + 1,
                             'reason', p_reason, 'supersedes', head.id),
          t.parameter_code || ' retested (' || p_reason || '), v' || head.version
            || ' preserved'
          || case when escalate is not null and n_prior > escalate
                  then ' · escalates to the GM: ' || n_prior || ' retests on one test'
                  else '' end);
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.pause_dev_clock()
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare t timestamptz;
begin
  perform public.assert_dev_clock_writer();
  select effective_now into t from public.get_effective_now();
  update public.dev_effective_clock
     set enabled = true,
         is_playing = false,
         effective_now = t,
         updated_at = clock_timestamp(),
         updated_by = auth.uid()
   where id = true;
  return t;
end;
$function$

