CREATE OR REPLACE FUNCTION public.publish_process_definition(p_definition uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d process_definition;
  s record;
begin
  perform public.assert_role(array['admin','gm']::app_role[], 'publish a process definition');

  select * into d from process_definition where id = p_definition;
  if not found then
    raise exception 'No such process definition: %', p_definition;
  end if;

  if d.status = 'published' then
    return;                                   -- idempotent. Publishing twice is not an error.
  end if;

  if d.status = 'archived' then
    raise exception
      '% v% is archived. An archived standard is history — publish a new version rather than '
      'reviving this one.', d.code, d.version
      using errcode = 'check_violation';
  end if;

  select * into s from v_process_envelope where process_definition_id = p_definition;

  if coalesce(s.activity_count, 0) = 0 then
    raise exception
      'Refusing to publish % v%: it has no activities. A published standard with nothing in it '
      'would generate an empty baseline and freeze it.', d.code, d.version
      using errcode = 'check_violation';
  end if;

  if s.unplaced_activity_count > 0 then
    raise exception
      'Refusing to publish % v%: % of its % activities carry no standard hour, so they cannot '
      'be placed on the axis and every batch built from it would freeze a baseline with holes.',
      d.code, d.version, s.unplaced_activity_count, s.activity_count
      using errcode = 'check_violation';
  end if;

  -- The SOP must agree with itself. Not "must equal 470" — 470 belongs to PROCESS-2026C and
  -- to nothing else. The rule is that a stated number and the activities beneath it describe
  -- the same process, whatever process that is.
  if s.envelope_disagrees then
    raise exception
      'Refusing to publish % v%: its activities compute a standard of %h, but a stated '
      'envelope of %h is recorded against it — a difference of %h. One of the two is wrong. '
      'Correct the activities or restate the envelope; do not publish a standard that '
      'disagrees with itself.',
      d.code, d.version, s.calculated_standard_hr, s.stated_envelope_hr,
      s.stated_minus_calculated_hr
      using errcode = 'check_violation';
  end if;

  update process_definition
     set status = 'published', published_by = auth.uid(), published_at = now()
   where id = p_definition;
end;
$function$

CREATE OR REPLACE FUNCTION public.raise_deviation(p_activity uuid, p_summary text, p_kind deviation_kind DEFAULT 'MANUAL'::deviation_kind, p_detail jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ba batch_activity; new_id uuid;
begin
  perform public.assert_role(array['operator','lab_tech','supervisor','gm']::app_role[],
                             'Raising a deviation');

  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;

  insert into deviation (master_batch_id, batch_activity_id, kind, summary, detail,
                         raised_by, raised_by_role)
  values (ba.master_batch_id, p_activity, p_kind, p_summary, coalesce(p_detail, '{}'::jsonb),
          auth.uid(), public.current_app_role())
  returning id into new_id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id,
                           after_state, reason)
  values (auth.uid(), public.current_app_role(), 'raise_deviation', 'deviation', new_id::text,
          p_detail, p_summary);

  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_checkpoint_decision(p_batch uuid, p_checkpoint integer, p_verdict text, p_reason text)
 RETURNS TABLE(decision_id uuid, checkpoint integer, verdict text, state text, decided_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b        master_batch;
  cp       management_checkpoint;
  new_id   uuid;
  v_role   app_role;
begin
  v_role := public.current_app_role();

  -- §2's matrix ticks "Approve management checkpoint 2–4" in the GM column and nowhere else. A
  -- supervisor holds release/hold/return on ACTIVITIES (B2); a management checkpoint is not theirs.
  if v_role is distinct from 'gm' then
    raise exception
      'Only the General Manager records a management checkpoint decision — % may not '
      '(ROLE_AND_APPROVAL_MODEL §2).', coalesce(v_role::text, 'an unknown role')
      using errcode = 'insufficient_privilege';
  end if;

  if p_verdict not in ('approved','approved_with_conditions','returned') then
    raise exception 'Verdict must be approved, approved_with_conditions or returned — got %', p_verdict;
  end if;

  -- MANDATORY, and checked here as well as by the column so the message names the reason rather than
  -- the constraint.
  if coalesce(btrim(p_reason), '') = '' then
    raise exception
      'A checkpoint decision needs a reason. §5''s return path is meaningless without one, and an '
      'approval with no stated basis cannot be reviewed.';
  end if;

  select * into b from master_batch where id = p_batch;
  if not found then raise exception 'No such batch: %', p_batch; end if;
  if b.status <> 'active' then
    raise exception 'Batch % is % — a checkpoint decision applies to a running batch', b.code, b.status;
  end if;

  -- The checkpoint is opened on first use. Nothing in `docs/` specifies an opener, and inventing a
  -- trigger that decides when a checkpoint becomes due would be inventing process.
  insert into management_checkpoint (master_batch_id, checkpoint_no)
  values (p_batch, p_checkpoint)
  on conflict (master_batch_id, checkpoint_no) do nothing;

  select * into cp from management_checkpoint
   where master_batch_id = p_batch and checkpoint_no = p_checkpoint;

  insert into checkpoint_decision (
    management_checkpoint_id, verdict, reason, package_snapshot, decided_by, decided_by_role)
  values (
    cp.id, p_verdict::checkpoint_verdict, btrim(p_reason),
    -- Snapshotted HERE, at the moment of the decision, from the server's own read. Not passed in by
    -- the client: a snapshot the caller supplies is a snapshot the caller can shade.
    public.checkpoint_package(p_batch, p_checkpoint),
    auth.uid(), v_role)
  returning id into new_id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id,
                           after_state, reason)
  values (auth.uid(), v_role, 'checkpoint_' || p_verdict, 'checkpoint_decision', new_id::text,
          jsonb_build_object('batch', b.code, 'checkpoint', p_checkpoint, 'verdict', p_verdict),
          btrim(p_reason));

  -- Whatever the gates now say becomes available. An approval does not open anything by itself; it
  -- satisfies one predicate, and `advance_batch` re-reads all of them.
  perform public.advance_batch(p_batch);

  return query
    select new_id, p_checkpoint, p_verdict,
           (select c.state::text from management_checkpoint c where c.id = cp.id),
           (select d.decided_at from checkpoint_decision d where d.id = new_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.record_lab_result(p_test uuid, p_numeric numeric DEFAULT NULL::numeric, p_text text DEFAULT NULL::text, p_instrument uuid DEFAULT NULL::uuid, p_invalid_reason text DEFAULT NULL::text, p_raw jsonb DEFAULT NULL::jsonb, p_measured_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t        lab_test;
  inst     lab_instrument;
  cal      lab_calibration_status := 'unknown';
  at_      timestamptz;
  existing int;
  new_id   uuid;
begin
  select * into t from lab_test where id = p_test;
  if not found then raise exception 'No such lab test: %', p_test; end if;

  select count(*) into existing from lab_result where test_id = p_test;
  if existing > 0 then
    raise exception
      'A result already exists for this test. Results are immutable and versioned — order a '
      'retest instead, which preserves the original (LAB_MODEL §5).'
      using errcode = 'unique_violation';
  end if;

  at_ := coalesce(p_measured_at, now());
  if at_ > now() then
    raise exception 'A measurement cannot be recorded in the future (% is ahead of now)', at_
      using errcode = 'invalid_datetime_format';
  end if;

  -- Calibration status is DERIVED where it can be, and 'unknown' where it cannot. No source gives
  -- a calibration interval in days, so an instrument without one reports 'unknown' — never
  -- 'valid'. Rule 2: the absence is stated, not defaulted away.
  if p_instrument is not null then
    select * into inst from lab_instrument where id = p_instrument;
    if not found then raise exception 'No such instrument: %', p_instrument; end if;
    if inst.last_calibrated_on is null or inst.calibration_interval_days is null then
      cal := 'unknown';
    elsif inst.last_calibrated_on + inst.calibration_interval_days >= current_date then
      cal := 'valid';
    else
      cal := 'expired';
    end if;
  end if;

  insert into lab_result (test_id, version, value_numeric, value_text, unit,
                          target_min, target_max, invalid_reason, measured_at, technician_id,
                          instrument_id, calibration_status, calibrated_on, raw_readings)
  values (t.id, 1, p_numeric, p_text, t.target_unit,
          t.target_min, t.target_max, p_invalid_reason, at_, auth.uid(),
          p_instrument, cal, inst.last_calibrated_on, p_raw)
  returning id into new_id;

  update lab_test set state = 'reported' where id = t.id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  select auth.uid(), public.current_app_role(), 'record_lab_result', 'lab_result', new_id::text,
         jsonb_build_object('parameter', t.parameter_code, 'value',
                            coalesce(p_numeric::text, p_text), 'verdict', r.verdict),
         t.parameter_code || ' = ' || coalesce(p_numeric::text, p_text, 'invalid')
           || ' · ' || r.verdict
  from lab_result r where r.id = new_id;
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_occupancy(p_activity uuid, p_from timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba     batch_activity;
  l      location;
  new_id uuid;
  clash  record;
begin
  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;
  if ba.destination_location_id is null then
    raise exception '% has no destination, so there is no vessel to occupy', ba.title;
  end if;
  select * into l from location where id = ba.destination_location_id;

  if p_from is null then
    raise exception
      'A window is required. Deriving one needs the bunker release rule, and that is unanswered — '
      'TBD-29 asks whether the source bunker is released at the start of the unload or at the end of '
      'the reload. Both readings are in resource_policy; neither is enabled.'
      using errcode = 'feature_not_supported';
  end if;

  begin
    insert into location_occupancy (
      location_id, master_batch_id, batch_activity_id, stream, started_at, ended_at, tbd_marker)
    values (l.id, ba.master_batch_id, ba.id, ba.stream, p_from, p_to,
            -- The row carries the question its window depends on, so a later reader knows the
            -- boundary was chosen by a caller and not derived from a stated rule.
            case when p_to is null then 'TBD-29' else null end)
    returning id into new_id;
  exception when exclusion_violation then
    select other.code as batch_code, oc.started_at, oc.ended_at
      into clash
      from location_occupancy oc
      join master_batch other on other.id = oc.master_batch_id
     where oc.location_id = l.id and oc.during && tstzrange(p_from, p_to)
     order by oc.started_at limit 1;
    raise exception
      '% is already held by % %. A bunker serves both streams, so a paddy occupancy blocks a '
      'compost occupancy exactly the same way (RESOURCE_MOVEMENT_MODEL §2).',
      l.label, clash.batch_code,
      case when clash.ended_at is null
           then 'from ' || clash.started_at || ' onwards, still held'
           else 'from ' || clash.started_at || ' to ' || clash.ended_at end
      using errcode = 'exclusion_violation';
  end;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'record_occupancy', 'location_occupancy',
          new_id::text,
          jsonb_build_object('location', l.code, 'from', p_from, 'to', p_to),
          l.label || ' held by ' || ba.title);
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.release_activity(p_activity uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ba batch_activity; still_open int;
begin
  perform public.assert_role(array['supervisor']::app_role[], 'Releasing an activity');
  if coalesce(trim(p_reason), '') = '' then
    raise exception 'A release needs a reason';
  end if;

  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity'; end if;

  -- §3.1 RELEASE requires "all exit-gate conditions satisfied, OR an accept-with-deviation on
  -- each failing one". So: nothing may still be awaiting a verdict.
  select count(*) into still_open
  from v_deviation_open
  where batch_activity_id = p_activity and awaiting_verdict;

  if still_open > 0 then
    raise exception
      'Cannot release — % deviation(s) still awaiting a verdict. Accept or resolve each one first.',
      still_open;
  end if;

  update batch_activity
     set state = 'COMPLETED', blocked_reason = null,
         actual_end = coalesce(actual_end, now())
   where id = p_activity;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'release_activity', 'batch_activity',
          p_activity::text, p_reason);

  -- Whatever this was holding up is re-evaluated by the gate engine, not by this function.
  perform public.advance_batch(ba.master_batch_id);
end;
$function$

CREATE OR REPLACE FUNCTION public.release_elapsed_rests(p_batch uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record;
begin
  perform public.assert_role(array['supervisor', 'admin', 'gm']::app_role[], 'release elapsed rests');

  select * into r from public.advance_batch(p_batch);
  return coalesce(r.opened, 0) + coalesce(r.resting, 0);
end;
$function$

CREATE OR REPLACE FUNCTION public.release_vessel(p_batch uuid, p_scope text, p_instance_no integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  a  batch_vessel_allocation;
  n  int;
begin
  select * into a from batch_vessel_allocation
   where master_batch_id = p_batch and scope = p_scope and instance_no = p_instance_no;
  if not found then return; end if;

  select count(*) into n from location_occupancy o
   where o.location_id = a.location_id and o.master_batch_id = p_batch;
  if n > 0 then
    raise exception
      'Work has already been recorded in this vessel. Releasing it would rewrite where the '
      'material actually was.'
      using errcode = 'invalid_parameter_value';
  end if;

  delete from batch_vessel_allocation where id = a.id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'release_vessel', 'batch_vessel_allocation',
          a.id::text, format('%s %s released', p_scope, p_instance_no));
end;
$function$

CREATE OR REPLACE FUNCTION public.render_gate_reason(p_template text, p_vars jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
declare
  out_text text := p_template;
  k text;
  v text;
begin
  for k, v in select * from jsonb_each_text(coalesce(p_vars, '{}'::jsonb)) loop
    out_text := replace(out_text, '{' || k || '}', coalesce(v, '—'));
  end loop;

  -- Anything the caller had no value for. Left in place it would render as `{machine_code}` on a
  -- card; replaced silently it would read as a fact nobody established.
  out_text := regexp_replace(out_text, '\{[a-z_]+\}', 'not recorded', 'g');
  return out_text;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_extension(p_activity uuid, p_hours numeric, p_reason text, p_evidence uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba  batch_activity;
  b   master_batch;
  pol extension_policy;
  n   int;
  new_id uuid;
begin
  select * into pol from extension_policy where extension_policy.id;
  perform public.assert_role(pol.requester_roles, 'Requesting an extension');

  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity: %', p_activity; end if;
  select * into b from master_batch where id = ba.master_batch_id;

  if b.status <> 'active' then
    raise exception 'Batch % is % — an extension only means something on a running batch', b.code, b.status;
  end if;

  if coalesce(trim(p_reason), '') = '' then
    raise exception 'An extension needs a reason — it is the whole record of why the plan was missed';
  end if;

  if p_hours is null or p_hours <= 0 then
    raise exception 'An extension must ask for a positive number of hours';
  end if;

  if pol.max_requested_hr is not null and p_hours > pol.max_requested_hr then
    raise exception 'An extension may not exceed % hours (extension_policy.max_requested_hr)',
      pol.max_requested_hr;
  end if;

  if pol.evidence_required and p_evidence is null then
    raise exception 'Policy requires evidence with an extension request (extension_policy.evidence_required)';
  end if;

  if not pol.allow_after_completion and ba.actual_end is not null then
    raise exception
      'Activity % has already finished. Extending it now would be rewriting history — record a deviation instead.',
      ba.code;
  end if;

  if not pol.allow_late_request
     and ba.planned_end_at is not null and now() > ba.planned_end_at then
    raise exception 'The planned end of % has passed and late requests are not permitted', ba.code;
  end if;

  if pol.max_total_per_activity is not null then
    select count(*) into n from extension_request where batch_activity_id = p_activity;
    if n >= pol.max_total_per_activity then
      raise exception 'Activity % already carries % extension request(s), the configured maximum',
        ba.code, n;
    end if;
  end if;

  -- The one-open-request rule is the partial unique index; this turns its
  -- constraint error into a sentence a person can act on.
  select count(*) into n from extension_request
   where batch_activity_id = p_activity and status in ('REQUESTED','MANAGER_APPROVED');
  if n >= pol.max_open_per_activity then
    raise exception 'Activity % already has an extension request awaiting a decision', ba.code;
  end if;

  insert into extension_request (
    master_batch_id, batch_activity_id,
    requested_by, requested_by_role, requested_extension_hr, requested_reason, evidence_id,
    planned_end_at_at_request, activity_state_at_request, status
  ) values (
    ba.master_batch_id, p_activity,
    auth.uid(), public.current_app_role(), p_hours, trim(p_reason), p_evidence,
    ba.planned_end_at, ba.state::text, 'REQUESTED'
  ) returning extension_request.id into new_id;

  insert into notification (master_batch_id, batch_activity_id, to_role, kind, message, reason, sent_by)
  values (ba.master_batch_id, p_activity, 'manager', 'alert',
          format('Extension requested on %s: %s hours', ba.title, p_hours), trim(p_reason), auth.uid());

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'request_extension', 'extension_request', new_id::text,
          jsonb_build_object('hours', p_hours, 'activity', p_activity, 'status', 'REQUESTED'),
          trim(p_reason));

  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.request_lab_test(p_sample uuid, p_parameter text, p_via text DEFAULT 'user'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s      lab_sample;
  cp     lab_checkpoint;
  spec   lab_spec;
  m      text;
  new_id uuid;
begin
  select * into s from lab_sample where id = p_sample;
  if not found then raise exception 'No such sample: %', p_sample; end if;
  select * into cp from lab_checkpoint where id = s.checkpoint_id;

  -- ── THE FREEZE ────────────────────────────────────────────────────────────
  -- Looked up only through `spec_checkpoint_code`, which is null wherever TBD-36 leaves the
  -- mapping unstated. So an unmapped checkpoint freezes NO band, `spec_found` stays false, and
  -- every result on it is `no_spec`. That is the honest outcome of an unanswered mapping — not a
  -- reason to guess which spec row was meant.
  if cp.spec_checkpoint_code is not null then
    select * into spec from lab_spec
     where checkpoint_code = cp.spec_checkpoint_code and parameter_code = p_parameter;
  end if;

  -- The method, where one exists for the parameter. `lab_method` is keyed by an upper-case code
  -- and the parameter vocabulary is lower-case; the join is by name, not by a mapping table,
  -- because no source states a parameter → method mapping beyond the shared name.
  select code into m from lab_method where code = upper(p_parameter);

  insert into lab_test (sample_id, parameter_code, method_code, requested_by, requested_via,
                        target_min, target_max, target_unit, spec_source_ref, spec_conflict_id,
                        spec_found)
  values (s.id, p_parameter, m, auth.uid(),
          case when p_via = 'system' then 'system' else 'user' end,
          spec.min_value, spec.max_value, spec.unit, spec.source_ref, spec.conflict_id,
          spec.id is not null)
  on conflict (sample_id, parameter_code) do update set
    -- Re-requesting the same parameter on the same sample must not silently re-freeze a band
    -- against a spec that may have changed. Only the method is refreshed.
    method_code = excluded.method_code
  returning id into new_id;

  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolve_activity_label(p_batch_id uuid, p_template text, p_material_role material_role_code, p_index integer DEFAULT NULL::integer)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  lead_name text;
  out_text  text := p_template;
begin
  if p_material_role is not null then
    select m.name into lead_name
    from public.batch_material_role bmr
    join public.material m on m.id = bmr.material_id
    where bmr.master_batch_id = p_batch_id
      and bmr.role = p_material_role
      and bmr.is_role_lead
    limit 1;
  end if;

  -- Guard every substitution: replace() with a NULL argument returns NULL, which would
  -- null the whole title. Material-agnostic activities carry no {role_lead} at all.
  if position('{role_lead}' in out_text) > 0 then
    out_text := replace(
      out_text, '{role_lead}',
      coalesce(lead_name, initcap(replace(coalesce(p_material_role::text, 'material'), '_', ' ')))
    );
  end if;

  if position('{n}' in out_text) > 0 then
    out_text := replace(out_text, '{n}', coalesce(p_index, 1)::text);
  end if;

  return out_text;
end;
$function$

CREATE OR REPLACE FUNCTION public.rls_auto_enable()
 RETURNS event_trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.send_alert(p_activity uuid, p_role app_role, p_message text, p_reason text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ba batch_activity; b master_batch; nid uuid; note text;
begin
  perform public.assert_role(array['gm', 'manager', 'admin', 'supervisor']::app_role[], 'send an alert');

  select * into ba from batch_activity where id = p_activity;
  select * into b from master_batch where id = ba.master_batch_id;

  if b.status = 'active' and coalesce(p_reason,'') = '' then
    raise exception 'An alert on a running batch needs a reason';
  end if;

  note := p_message;
  if ba.state = 'LOCKED' then
    note := note || ' (note: this task is still locked — ' || coalesce(ba.blocked_reason,'waiting') || ')';
  end if;

  insert into notification (master_batch_id, batch_activity_id, to_role, kind, message, reason, sent_by)
  values (ba.master_batch_id, p_activity, p_role, 'alert', note, p_reason, auth.uid())
  returning id into nid;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'send_alert', 'batch_activity', p_activity::text,
          coalesce(p_reason, p_message));
  return nid;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_activity_plan(p_activity uuid, p_patch jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba batch_activity;
  b  master_batch;
  src uuid;
begin
  perform public.assert_role(array['admin', 'gm', 'supervisor']::app_role[], 'change a planned time');

  select * into ba from batch_activity where id = p_activity;
  if not found then raise exception 'No such activity'; end if;

  select * into b from master_batch where id = ba.master_batch_id;
  if b.status <> 'draft' then
    raise exception 'The baseline is frozen — % is %. Change goes through a deviation or an override.', b.code, b.status;
  end if;

  update batch_activity set
    day0_duration_hr        = coalesce(nullif(p_patch->>'day0_duration_hr','')::numeric, day0_duration_hr),
    planned_qty_override_mt = coalesce(nullif(p_patch->>'planned_qty_override_mt','')::numeric, planned_qty_override_mt),
    planned_time            = coalesce(nullif(p_patch->>'planned_time','')::time, planned_time),
    responsible_role        = coalesce(nullif(p_patch->>'responsible_role','')::app_role, responsible_role),
    assigned_person_id      = case when p_patch ? 'assigned_person_id'
                                  then nullif(p_patch->>'assigned_person_id','')::uuid
                                  else assigned_person_id end,
    assigned_machine_id     = case when p_patch ? 'assigned_machine_id'
                                  then nullif(p_patch->>'assigned_machine_id','')::uuid
                                  else assigned_machine_id end,
    assigned_vehicle_id     = case when p_patch ? 'assigned_vehicle_id'
                                  then nullif(p_patch->>'assigned_vehicle_id','')::uuid
                                  else assigned_vehicle_id end,
    destination_location_id = case when p_patch ? 'destination_location_id'
                                  then nullif(p_patch->>'destination_location_id','')::uuid
                                  else destination_location_id end,
    source_location_id      = case when p_patch ? 'source_location_id'
                                  then nullif(p_patch->>'source_location_id','')::uuid
                                  else source_location_id end,
    variant_code            = case when p_patch ? 'variant_code'
                                  then nullif(p_patch->>'variant_code','')
                                  else variant_code end,
    variant_reason          = coalesce(nullif(p_patch->>'variant_reason',''), variant_reason)
  where id = p_activity;

  -- A reload's source is whatever the previous stint used. Inherited, not typed.
  if p_patch ? 'destination_location_id' then
    select destination_location_id into src
    from batch_activity prev
    where prev.master_batch_id = ba.master_batch_id
      and prev.instance_no = ba.instance_no
      and prev.seq < ba.seq
      and prev.destination_location_id is not null
    order by prev.seq desc limit 1;

    if src is not null and ba.source_location_id is null then
      update batch_activity set source_location_id = src where id = p_activity;
    end if;
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_batch_start_at(p_batch uuid, p_start_at timestamp with time zone)
 RETURNS TABLE(activities_repointed integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare b master_batch;
begin
  perform public.assert_role(array['admin', 'gm']::app_role[], 'set H0');

  select * into b from master_batch where id = p_batch;
  if not found then raise exception 'No such batch: %', p_batch; end if;
  if b.status <> 'draft' then
    raise exception 'Batch % is % — H0 is frozen at activation', b.code, b.status;
  end if;
  if p_start_at is null then
    raise exception 'H0 is mandatory and never defaults. TIME_CONTRACT §1.1';
  end if;

  update master_batch set start_at = p_start_at where id = p_batch;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'set_batch_start_at', 'master_batch',
          p_batch::text, jsonb_build_object('start_at', p_start_at), 'H0 set');

  return query select public.repoint_batch_activities(p_batch);
end;
$function$

CREATE OR REPLACE FUNCTION public.set_current_process(p_definition uuid, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d process_definition;
begin
  perform public.assert_role(array['admin','gm']::app_role[], 'change the current process standard');

  select * into d from process_definition where id = p_definition;
  if not found then
    raise exception 'No such process definition: %', p_definition;
  end if;

  if d.status <> 'published' then
    raise exception
      'Cannot make % v% the current standard while it is %. Publish it first — '
      'select public.publish_process_definition(''%'').', d.code, d.version, d.status, p_definition
      using errcode = 'check_violation';
  end if;

  insert into process_catalogue (id, current_definition_id, set_by, set_at, reason)
  values (1, p_definition, auth.uid(), now(), p_reason)
  on conflict (id) do update set
    current_definition_id = excluded.current_definition_id,
    set_by = excluded.set_by, set_at = excluded.set_at, reason = excluded.reason;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_dev_clock_h(p_batch uuid, p_h integer)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  h0 timestamptz;
  target timestamptz;
begin
  perform public.assert_dev_clock_writer();
  if p_h < 0 then
    raise exception 'DEV_CLOCK_INVALID_H: H must be zero or greater' using errcode = 'invalid_parameter_value';
  end if;

  select start_at into h0 from public.master_batch where id = p_batch;
  if h0 is null then
    raise exception 'DEV_CLOCK_NO_H0: batch has no explicit H0' using errcode = 'invalid_parameter_value';
  end if;

  target := h0 + make_interval(hours => p_h);
  update public.dev_effective_clock
     set enabled = true,
         is_playing = false,
         effective_now = target,
         updated_at = clock_timestamp(),
         updated_by = auth.uid()
   where id = true;

  insert into public.audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'DEV_CLOCK_SET_H', 'master_batch', p_batch::text,
          format('Development effective time set to H%s', p_h));
  return target;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_individual_batches(p_batch uuid, p_numbers text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  b     master_batch;
  parts text[];
  n     text;
  i     int := 0;
  made  int := 0;
begin
  select * into b from master_batch where id = p_batch;
  if not found then raise exception 'No such batch'; end if;
  if b.status <> 'draft' then
    raise exception
      'The baseline is frozen - % is %. The batches it covers cannot change now.', b.code, b.status;
  end if;

  -- Split on comma, slash or whitespace: the records use all three.
  parts := regexp_split_to_array(btrim(p_numbers), '[[:space:],/]+');

  delete from individual_batch where master_batch_id = p_batch;

  foreach n in array parts loop
    n := btrim(n);
    continue when n = '';
    i := i + 1;
    insert into individual_batch (master_batch_id, batch_no, seq) values (p_batch, n, i);
    made := made + 1;
  end loop;

  if made = 0 then
    raise exception 'No batch numbers found in "%". Write them as the factory does: 366,367,368',
      p_numbers using errcode = 'invalid_parameter_value';
  end if;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'set_individual_batches', 'master_batch',
          p_batch::text, format('%s covers %s', b.code, p_numbers));
  return made;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_movement_vessel(p_batch uuid, p_movement text, p_location uuid, p_individual uuid DEFAULT NULL::uuid, p_planned_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  t      movement_template;
  loc    location;
  b      master_batch;
  clash  record;
  prev   uuid;
  new_id uuid;
begin
  select * into t from movement_template where code = p_movement;
  if not found then raise exception 'Unknown movement "%"', p_movement; end if;

  select * into b from master_batch where id = p_batch;
  if not found then raise exception 'No such batch'; end if;

  if t.is_per_individual_batch and p_individual is null then
    raise exception '% is chosen for each individual batch, so one must be named.', t.label
      using errcode = 'invalid_parameter_value';
  end if;
  if not t.is_per_individual_batch and p_individual is not null then
    raise exception '% is made by the whole master batch together.', t.label
      using errcode = 'invalid_parameter_value';
  end if;

  select * into loc from location where id = p_location;
  if not found then raise exception 'No such location'; end if;
  if t.vessel_kind is not null and loc.kind <> t.vessel_kind then
    raise exception '% needs a % - % is a %.', t.label, t.vessel_kind, loc.label, loc.kind
      using errcode = 'invalid_parameter_value';
  end if;
  if loc.status is distinct from 'available' then
    raise exception '% is not available (%).', loc.label, loc.status
      using errcode = 'invalid_parameter_value';
  end if;

  -- Held by ANOTHER batch right now. A batch returning to a bunker it used earlier is fine and the
  -- records show it happening, so this only looks at other batches.
  if loc.is_exclusive then
    select mb.code, o.started_at into clash
      from location_occupancy o
      join master_batch mb on mb.id = o.master_batch_id
     where o.location_id = p_location and o.ended_at is null and o.master_batch_id <> p_batch
     limit 1;
    if found then
      raise exception '% is occupied by % since %, and has not been released.',
        loc.label, clash.code, to_char(clash.started_at, 'DD Mon HH24:MI')
        using errcode = 'exclusion_violation';
    end if;
  end if;

  -- Where it comes FROM is the vessel of the previous movement, so the chain draws itself.
  select bm.to_location_id into prev
    from batch_movement bm
    join movement_template mt on mt.code = bm.movement_code
   where bm.master_batch_id = p_batch
     and mt.seq < t.seq
     and (bm.individual_batch_id is null or bm.individual_batch_id = p_individual)
     and bm.to_location_id is not null
   order by mt.seq desc limit 1;

  if p_individual is null then
    delete from batch_movement
     where master_batch_id = p_batch and movement_code = p_movement and individual_batch_id is null;
  else
    delete from batch_movement
     where master_batch_id = p_batch and movement_code = p_movement
       and individual_batch_id = p_individual;
  end if;

  insert into batch_movement
    (master_batch_id, individual_batch_id, movement_code, from_location_id, to_location_id,
     planned_at, note, recorded_by)
  values (p_batch, p_individual, p_movement, prev, p_location, p_planned_at, p_note, auth.uid())
  returning id into new_id;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, after_state, reason)
  values (auth.uid(), public.current_app_role(), 'set_movement_vessel', 'batch_movement',
          new_id::text, jsonb_build_object('movement', p_movement, 'location', loc.code),
          format('%s goes to %s', t.label, loc.label));
  return new_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_process_envelope(p_definition uuid, p_hours integer, p_confidence process_confidence, p_source_ref text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  d          process_definition;
  calculated numeric;
begin
  perform public.assert_role(array['admin','gm']::app_role[], 'state a process envelope');

  select * into d from process_definition where id = p_definition;
  if not found then
    raise exception 'No such process definition: %', p_definition;
  end if;

  if d.status <> 'draft' then
    raise exception
      'The standard % v% is % - its envelope is frozen. Publish a new version instead of editing this one.',
      d.code, d.version, d.status
      using errcode = 'check_violation';
  end if;

  if p_confidence = 'UNRESOLVED' then
    raise exception
      'An envelope of %h cannot be stored as UNRESOLVED. If nobody has ruled on the number, do not store the number - leave it null and the day grid stands in.',
      p_hours
      using errcode = 'check_violation';
  end if;

  if coalesce(trim(p_source_ref), '') = '' then
    raise exception
      'An envelope needs a source. Who stated %h, and where? A number with no provenance is how 552 became the factory standard.',
      p_hours
      using errcode = 'check_violation';
  end if;

  -- 0045. A definition with activities already states its own length; a stated envelope that
  -- contradicts them is caught here, where the person stating it can still see why.
  select calculated_standard_hr into calculated
    from v_process_standard where process_definition_id = p_definition;

  if calculated is not null and calculated <> p_hours then
    raise exception
      'Refusing to record an envelope of %h against % v%: its own activities compute %h. '
      'The standard is what the process does. Correct the activities, or state the number the '
      'process actually produces.',
      p_hours, d.code, d.version, calculated
      using errcode = 'check_violation';
  end if;

  update process_definition
     set envelope_hours       = p_hours,
         envelope_hour_source = 'factory_stated',
         envelope_confidence  = p_confidence,
         source_ref           = p_source_ref
   where id = p_definition;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_activity(p_activity uuid, p_values jsonb DEFAULT '{}'::jsonb, p_remarks text DEFAULT NULL::text, p_actual_start timestamp with time zone DEFAULT NULL::timestamp with time zone, p_actual_end timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(new_state text, out_of_range integer, outstanding_evidence text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  ba          batch_activity;
  b           master_batch;
  k           text;
  v           text;
  fld         batch_activity_value;
  flag        text;
  target      numeric;
  target_src  text;
  dev_count   int := 0;
  reasons     text := '';
  outstanding text;
  entered_at  timestamptz := now();
  h0          timestamptz;
  eff_start   timestamptz;
  eff_end     timestamptz;
  -- Each failing field, captured so the deviation rows can be written after the state settles.
  fails       jsonb := '[]'::jsonb;
  f           jsonb;
begin
  perform public.assert_role(array['operator', 'supervisor', 'lab_tech']::app_role[], 'submit an activity');

  -- 0071 · LOCK THE ROW, THEN DECIDE.
  -- The state check below is a read followed by a write. Five phones submitting at once all read
  -- IN_PROGRESS, and two of them got through before either had committed — one completion, one
  -- actual_end, but two 'submit_activity' rows in the trail. Taking the row lock here serialises
  -- them, so the second caller re-reads a COMPLETED row and receives the refusal that already
  -- exists a few lines below.
  select * into ba from batch_activity where id = p_activity for update;
  if not found then raise exception 'No such activity: %', p_activity; end if;
  -- 0050 · An operator records work by doing it, not by typing when it happened.
  if (p_actual_start is not null or p_actual_end is not null)
     and coalesce(public.current_app_role()::text, '') = 'operator' then
    raise exception
      'An operator may not state a start or end time. Use start_activity and '
      'complete_activity and the server records when it happened. If a time has to be '
      'entered after the fact, a supervisor does it.'
      using errcode = 'insufficient_privilege';
  end if;


  select * into b from master_batch where id = ba.master_batch_id;
  if b.status <> 'active' then
    raise exception 'Batch % is % — activate it before recording work', b.code, b.status;
  end if;
  if ba.state not in ('READY','IN_PROGRESS','RETURNED') then
    raise exception '% is %, so it cannot be submitted', ba.title, ba.state;
  end if;

  -- 0071 · AN OPERATOR CANNOT FINISH WHAT THEY NEVER STARTED.
  --
  -- Submitting from READY is deliberate and stays: a supervisor recording a paper slip after the
  -- fact has no start_activity call to lean on. But for an OPERATOR it produced a quiet lie. One
  -- stray tap on Finish stamped actual_start = now() for work that never began, and
  -- fn_actual_is_append_only then makes that stamp permanent — there is no un-happen, by design.
  -- So the mistake is unrecoverable, which is the wrong price for a mis-tap on a factory phone.
  --
  -- The refusal names the fix, because the operator's own screen has the button.
  if ba.actual_start is null
     and coalesce(public.current_app_role()::text, '') = 'operator' then
    raise exception
      '% has not been started, so it cannot be finished. Tap Start on the task first — the server '
      'records when it began.', ba.title
      using errcode = 'check_violation';
  end if;

  -- ── Recorded actuals are validated BEFORE anything is written ─────────────
  -- Carried unchanged from 0016. A refusal must leave the row exactly as it was, and a refusal an
  -- operator cannot act on is barely better than a silent one — so every message names the
  -- activity and the value it rejected.

  if p_actual_start is not null and p_actual_start > entered_at then
    raise exception
      'Cannot record a start of % for %: that is in the future. An actual is something that has '
      'already happened.', p_actual_start, ba.title
      using errcode = 'invalid_datetime_format';
  end if;

  if p_actual_end is not null and p_actual_end > entered_at then
    raise exception
      'Cannot record an end of % for %: that is in the future. An actual is something that has '
      'already happened.', p_actual_end, ba.title
      using errcode = 'invalid_datetime_format';
  end if;

  -- The EFFECTIVE pair, so a stated end earlier than an already-recorded start is refused too —
  -- start_activity may have written actual_start when the operator opened the card.
  eff_start := coalesce(p_actual_start, ba.actual_start);
  eff_end   := coalesce(p_actual_end, ba.actual_end);

  if eff_start is not null and eff_end is not null and eff_end < eff_start then
    raise exception
      'Cannot record % ending at % when it started at %: work does not end before it begins.',
      ba.title, eff_end, eff_start
      using errcode = 'invalid_datetime_format';
  end if;

  -- NEW in B2 · a STATED actual may not precede H0. `batchHour()` already throws on it —
  -- "nothing in a batch happens before H0" — so the server agrees with the domain function
  -- rather than accepting what the client would refuse to render.
  --
  -- SCOPED TO WHAT THE SUBMITTER STATES, deliberately. Applying it to the `now()` default would
  -- also refuse a live recording on a batch whose `start_at` is still in the future — and that
  -- situation is reachable today: `activate_batch` does not require H0 to have passed, and
  -- `start_activity` stamps `now()` with no H0 check, so an activity can already carry an
  -- `actual_start` a month before its own batch began. Refusing at submit would strand an
  -- operator over a value they did not state.
  --
  -- That incoherence is REAL and PRE-EXISTING, and it is registered as TBD-52 rather than
  -- resolved here: whether "active" should mean "started" is a factory question, and answering
  -- it inside a deviations migration would be the wrong place and the wrong authority.
  h0 := b.start_at;
  if h0 is not null and p_actual_start is not null and p_actual_start < h0 then
    raise exception
      'Cannot record % starting at %: the batch begins at % and nothing in it happens before '
      'that.', ba.title, p_actual_start, h0
      using errcode = 'invalid_datetime_format';
  end if;
  if h0 is not null and p_actual_end is not null and p_actual_end < h0 then
    raise exception
      'Cannot record % ending at %: the batch begins at % and nothing in it happens before '
      'that.', ba.title, p_actual_end, h0
      using errcode = 'invalid_datetime_format';
  end if;

  for k, v in select * from jsonb_each_text(p_values) loop
    select * into fld from batch_activity_value
     where batch_activity_id = p_activity and field_key = k;
    continue when not found;

    flag := 'not_applicable';

    if v ~ '^-?[0-9]+(\.[0-9]+)?$' then
      target := null;
      target_src := null;

      if fld.day0_value ~ '^-?[0-9]+(\.[0-9]+)?$' then
        target := fld.day0_value::numeric;
        target_src := 'the Day-0 plan';
      elsif ba.planned_qty_mt is not null and k like '%qty%' then
        target := ba.planned_qty_mt;
        target_src := 'the Day-0 plan';
      end if;

      if fld.sop_min is not null or fld.sop_max is not null then
        if (fld.sop_min is not null and v::numeric < fld.sop_min)
           or (fld.sop_max is not null and v::numeric > fld.sop_max) then
          flag := 'out_of_range';
          dev_count := dev_count + 1;
          reasons := reasons || fld.label || ' ' || v || coalesce(' ' || fld.unit,'')
                     || ' outside the SOP band ' || coalesce(fld.sop_min::text,'')
                     || '–' || coalesce(fld.sop_max::text,'') || '; ';
          fails := fails || jsonb_build_object(
            'kind', 'VALUE_OUT_OF_SOP',
            'summary', fld.label || ' ' || v || coalesce(' ' || fld.unit,'')
                       || ' is outside the SOP band '
                       || coalesce(fld.sop_min::text,'') || '–' || coalesce(fld.sop_max::text,''),
            'detail', jsonb_build_object(
              'field_key', k, 'label', fld.label, 'value', v, 'unit', fld.unit,
              'sop_min', fld.sop_min, 'sop_max', fld.sop_max,
              'sop_source_ref', fld.sop_source_ref, 'conflict_id', fld.conflict_id,
              'day0_value', fld.day0_value));
        else
          flag := 'in_range';
        end if;

      elsif target is not null and target > 0 then
        if abs(v::numeric - target) / target > 0.10 then
          flag := 'out_of_range';
          dev_count := dev_count + 1;
          reasons := reasons || fld.label || ' ' || v || coalesce(' ' || fld.unit,'')
                     || ' against ' || target || coalesce(' ' || fld.unit,'')
                     || ' in ' || target_src || ' ('
                     || case when v::numeric > target then '+' else '' end
                     || round(v::numeric - target, 2) || '); ';
          fails := fails || jsonb_build_object(
            'kind', 'VALUE_OFF_DAY0_TARGET',
            'summary', fld.label || ' ' || v || coalesce(' ' || fld.unit,'')
                       || ' against ' || target || coalesce(' ' || fld.unit,'')
                       || ' planned at Day 0 ('
                       || case when v::numeric > target then '+' else '' end
                       || round(v::numeric - target, 2) || ')',
            'detail', jsonb_build_object(
              'field_key', k, 'label', fld.label, 'value', v, 'unit', fld.unit,
              'target', target, 'target_source', target_src,
              'tolerance_pct', 10, 'conflict_id', fld.conflict_id,
              -- No SOP band exists here. Saying so is information: docs/LAB_MODEL.md §9.
              'sop_source_ref', fld.sop_source_ref));
        else
          flag := 'in_range';
        end if;
      end if;
    end if;

    update batch_activity_value
       set actual_value = v,
           actual_recorded_at = entered_at,
           actual_recorded_by = auth.uid(),
           variance_flag = flag,
           remarks = coalesce(nullif(p_remarks,''), remarks)
     where id = fld.id;
  end loop;

  select gv.reason into outstanding
  from public.evaluate_gates(p_activity, 'exit') gv
  where gv.kind = 'EVIDENCE_COMPLETE' and gv.verdict = 'fail'
  order by gv.ordering
  limit 1;

  if outstanding is not null then
    update batch_activity
       set state = 'IN_PROGRESS',
           actual_start = coalesce(actual_start, p_actual_start, entered_at),
           actual_end = coalesce(actual_end, p_actual_end),
           actual_recorded_at = entered_at,
           blocked_reason = null
     where id = p_activity;

    insert into audit_event (actor_id, actor_role, action, entity_table, entity_id,
                             after_state, reason)
    values (auth.uid(), public.current_app_role(), 'submit_blocked_on_evidence',
            'batch_activity', p_activity::text,
            jsonb_build_object('actual_start', p_actual_start, 'actual_end', p_actual_end,
                               'recorded_at', entered_at),
            outstanding);

    return query select 'IN_PROGRESS'::text, dev_count, outstanding;
    return;
  end if;

  update batch_activity
     set state = case when dev_count > 0 then 'DEVIATION'::activity_state
                      else 'COMPLETED'::activity_state end,
         actual_start = coalesce(actual_start, p_actual_start, entered_at),
         actual_end = coalesce(actual_end, p_actual_end, entered_at),
         actual_recorded_at = entered_at,
         submitted_at = entered_at,
         submitted_by = auth.uid(),
         blocked_reason = case when dev_count > 0
           then rtrim(reasons, '; ') || ' — held for supervisor review' end
   where id = p_activity;

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id,
                           after_state, reason)
  select auth.uid(), public.current_app_role(), 'submit_activity', 'batch_activity',
         p_activity::text,
         jsonb_build_object(
           'actual_start', cur.actual_start,
           'actual_end', cur.actual_end,
           'recorded_at', cur.actual_recorded_at,
           'duration_actual_min', cur.duration_actual_min,
           'variance_minutes', cur.variance_minutes,
           'stated_by_submitter', (p_actual_start is not null or p_actual_end is not null)),
         case when dev_count > 0 then 'DEVIATION · ' || rtrim(reasons,'; ')
              else coalesce(nullif(p_remarks,''), 'submitted') end
    from batch_activity cur where cur.id = p_activity;

  -- ── B2 · every failing field becomes a record someone can act on ──────────────
  -- One row per failing condition, not one per submission: §3.1 waives "one failing condition"
  -- at a time, so a supervisor must be able to accept one and refuse another.
  for f in select * from jsonb_array_elements(fails) loop
    insert into deviation (master_batch_id, batch_activity_id, kind, summary, detail,
                           raised_by, raised_by_role)
    values (ba.master_batch_id, p_activity, (f->>'kind')::deviation_kind,
            f->>'summary', f->'detail', auth.uid(), public.current_app_role());
  end loop;

  if dev_count = 0 then
    perform public.advance_batch(ba.master_batch_id);
  else
    update batch_activity nxt
       set state = 'BLOCKED',
           blocked_reason = 'Blocked — ' || ba.title || ' (' || ba.scope_label
                            || ') is in deviation: ' || rtrim(reasons, '; ')
     where nxt.master_batch_id = ba.master_batch_id
       and nxt.stream = ba.stream
       and nxt.seq > ba.seq
       and nxt.state in ('LOCKED','READY','WAITING_TIME')
       and nxt.seq = (
         select min(n2.seq) from batch_activity n2
         where n2.master_batch_id = ba.master_batch_id
           and n2.stream = ba.stream
           and n2.seq > ba.seq
           and n2.state in ('LOCKED','READY','WAITING_TIME'));
  end if;

  return query
    select (select state::text from batch_activity where id = p_activity), dev_count, null::text;
end;
$function$

CREATE OR REPLACE FUNCTION public.verify_corrective_action(p_action uuid, p_note text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare dev uuid;
begin
  perform public.assert_role(array['supervisor','gm']::app_role[],
                             'Verifying a corrective action');
  if coalesce(trim(p_note), '') = '' then
    raise exception 'Verifying a corrective action needs a note saying what proved it';
  end if;

  update corrective_action
     set verified_at = now(), verified_by = auth.uid(), verification_note = p_note
   where id = p_action
  returning deviation_id into dev;
  if dev is null then raise exception 'No such corrective action'; end if;

  -- A deviation resolves only when a corrective action has been VERIFIED. Doing the work is not
  -- the same claim as the work having worked.
  update deviation
     set state = 'resolved', decided_at = now(), decided_by = auth.uid(),
         decided_by_role = public.current_app_role(),
         decision_reason = coalesce(nullif(decision_reason, ''), p_note)
   where id = dev and state in ('open', 'accepted', 'escalated');

  insert into audit_event (actor_id, actor_role, action, entity_table, entity_id, reason)
  values (auth.uid(), public.current_app_role(), 'verify_corrective_action',
          'corrective_action', p_action::text, p_note);
end;
$function$
